275	    let y2 = x_coord.mul_mod(&x_coord).mul_mod(&x_coord).add_mod(&U256::from_u64(7));
276	    let e = U256([0xffffffffbfffff0c, 0xffffffffffffffff, 0xffffffffffffffff, 0x3fffffffffffffff]);
