        let kG = ec_mul(&private_key, &G);
        kG.equals(public_key)
    } else {
        false
    };

    // Certify topological advantage (winding bridge)
    let advantage = certify_advantage(&shor_params);

    ShorsBtc2Result {
        success: pk_found || verified,
