1	// ─── counterfactual.rs ─────────────────────────────────────────────────
2	// "What if I perturb reality?" (build.txt §7)
3	//
4	// A structural sensitivity analyzer. Perturb one glyph and read what moved:
5	// which invariants held, which broke, whether the perturbation can be undone,
6	// and the smallest repair that puts the word back in its original basin.
7	//
8	// It owns no semantics of its own. The verdict and register come from
9	// imasm_core, the banking walk from lattice_flow, and the repair search is the
10	// same exact single-glyph sweep `insert` uses. This tool only *compares* two
11	// walks — which is the whole point: discovering which symbols actually matter
12	// rather than merely correlating with an outcome.
13	#![allow(dead_code)]
14	
15	extern crate alloc;
16	use alloc::format;
17	use alloc::string::{String, ToString};
18	use alloc::vec::Vec;
19	
20	use imasm_core::imasm16_3::{parse_glyph_word, run_word_register, tri_ancestral_verdict};
21	
22	use crate::lattice_flow::{banked_walk, normalize};
23	
24	/// The twelve marks, in canonical order.
25	pub const MARKS: [char; 12] = ['⊢', '⊣', '>', '<', '⋈', '⊙', '∈', '∋', '⊤', '⊥', '⊞', '◻'];
26	
27	/// Everything one walk knows about a word. Compared field-by-field against
28	/// the perturbed walk to produce the held/broken split.
29	#[derive(Clone, PartialEq)]
30	pub struct Reading {
31	    pub word: String,
32	    pub length: usize,
33	    pub verdict: char,
34	    pub verdict_why: String,
35	    pub register: String,
36	    pub holds: bool,
37	    pub vacuous: bool,
38	    pub live_clears: u32,
39	    pub deposits: u32,
40	    pub inert: u32,
41	    pub exposed: usize,
42	}
43	
44	pub fn read(word: &str) -> Option<Reading> {
45	    let norm = normalize(word);
46	    let steps = parse_glyph_word(&norm);
47	    if steps.is_empty() {
48	        return None;
49	    }
50	    let (verdict, why) = tri_ancestral_verdict(&steps);
51	    let b = banked_walk(&norm)?;
52	    Some(Reading {
53	        word: norm,
54	        length: steps.len(),
55	        verdict,
56	        verdict_why: why,
57	        register: run_word_register(&steps),
58	        holds: b.holds(),
59	        vacuous: b.vacuous(),
60	        live_clears: b.live_clears,
61	        deposits: b.deposits,
62	        inert: b.inert,
63	        exposed: b.exposed.len(),
64	    })
65	}
