85	    /// A perturbation is reversible when an inverse perturbation exists that
86	    /// restores the word exactly. Rotation always has one. Replacement has one
87	    /// only when the replaced mark is not already present elsewhere, otherwise
88	    /// the inverse would also rewrite an untouched occurrence. Deletion loses
89	    /// the position and insertion of a duplicate loses which copy was added.
90	    pub fn reversible(&self, original: &str) -> (bool, &'static str) {
91	        match self {
92	            Perturbation::Rotate(_) => (true, "rotate by -k restores the word"),
93	            Perturbation::Replace(_a, b) => {
94	                let count_b = original.chars().filter(|c| c == b).count();
95	                if count_b == 0 {
96	                    (true, "the target mark was absent, so replacing back is unambiguous")
97	                } else {
98	                    (false, "the target mark already occurs, so the inverse cannot tell the copies apart")
99	                }
100	            }
101	            Perturbation::Delete(_) => (false, "deletion discards the position"),
102	            Perturbation::Insert(_, _) => (true, "delete at the same position restores the word"),
103	        }
104	    }
105	}
