107	pub fn apply(word: &str, p: Perturbation) -> String {
108	    let chars: Vec<char> = normalize(word).chars().collect();
109	    if chars.is_empty() {
110	        return String::new();
111	    }
112	    match p {
113	        Perturbation::Replace(from, to) => chars
114	            .iter()
115	            .map(|&c| if c == from { to } else { c })
116	            .collect(),
117	        Perturbation::Delete(g) => chars.iter().filter(|&&c| c != g).collect(),
118	        Perturbation::Insert(g, pos) => {
119	            let mut v = chars.clone();
120	            let at = pos.min(v.len());
121	            v.insert(at, g);
122	            v.into_iter().collect()
123	        }
124	        Perturbation::Rotate(k) => {
125	            let n = chars.len() as isize;
126	            let shift = ((k % n) + n) % n;
127	            let mut v: Vec<char> = Vec::with_capacity(chars.len());
128	            for i in 0..chars.len() {
129	                v.push(chars[((i as isize + shift) % n) as usize]);
130	            }
131	            v.into_iter().collect()
132	        }
133	    }
134	}
