1	// ─── V⊙x — Control-flow Closure Auditor ────────────────────
2	// Native Rust implementation of the Belnap FOUR control-flow auditor.
3	// Lifts program CFGs to twelve-glyph IMASM words and runs SIXTEEN_3 verdict.
4	#![allow(dead_code)]
5	
6	use alloc::vec::Vec;
7	use alloc::collections::BTreeMap;
8	use alloc::string::String;
9	use alloc::format;
10	use alloc::vec;
11	
12	// 12 IMASM opcodes as chars
13	pub const VINIT: char = '⊢';
14	pub const TANCH: char = '⊣';
15	pub const AFWD: char = '≻';
16	pub const AREV: char = '≺';
17	pub const FSPLIT: char = '∈';
18	pub const FFUSE: char = '∋';
19	pub const IMSCRIB: char = '⊙';
20	pub const IFIX: char = '⊡';
21	pub const CLINK: char = '⋈';
22	pub const EVALT: char = '⊤';
23	pub const EVALF: char = '⊥';
24	pub const ENGAGR: char = '⊞';
25	
26	/// A decoded instruction from a binary.
27	#[derive(Clone, Debug)]
28	pub struct Instruction {
29	    pub address: u64,
30	    pub mnemonic: String,
31	    pub op_str: String,
32	}
33	
34	/// Mnemonic prefixes that don't change classification
35	const MNEMONIC_PREFIXES: &[&str] = &["notrack ", "lock ", "bnd ", "rep ", "repe ", "repne ", "data16 "];
36	
37	/// Strip mnemonic prefixes so classification is consistent
38	pub fn strip_prefix(mn: &str) -> &str {
39	    for p in MNEMONIC_PREFIXES {
40	        if mn.starts_with(p) {
41	            return &mn[p.len()..];
42	        }
43	    }
44	    mn
45	}
46	
47	/// Parse a hex immediate from operand string
48	fn parse_imm(op_str: &str) -> Option<u64> {
49	    let s = op_str.trim();
50	    if s.starts_with("0x") || s.starts_with("0X") {
51	        u64::from_str_radix(&s[2..], 16).ok()
52	    } else {
53	        None
54	    }
55	}
56	
57	/// Check if operand string indicates an immediate (direct target)
58	fn is_direct(op_str: &str) -> bool {
59	    let s = op_str.trim();
60	    parse_imm(s).is_some()
61	}
62	
63	/// Check if the operand indicates a memory write (destination ends with ']')
64	fn writes_memory(op_str: &str) -> bool {
65	    let dst = op_str.split(',').next().unwrap_or("").trim();
66	    dst.ends_with(']')
67	}
68	
69	/// Move instructions (data movement between slots)
70	const MOVE_OPS: &[&str] = &["mov", "movzx", "movsx", "movsxd", "movabs",
71	    "movaps", "movdqa", "movdqu", "movups", "movd", "movq",
72	    "lea", "push", "pop", "xchg", "leave"];
73	
74	/// Arithmetic/logic instructions (engagement)
75	const ENGAGE_OPS: &[&str] = &["add", "sub", "adc", "sbb", "imul", "mul", "idiv", "div",
76	    "and", "or", "xor", "not", "neg", "inc", "dec", "shl", "shr", "sar", "rol",
77	    "ror", "sal", "bt", "bsf", "bsr", "popcnt", "cdq", "cqo", "cwde",
78	    "pushfd", "pushfq", "popfd", "popfq", "lahf", "sahf"];
79	
80	/// Terminal instructions
81	const TERMINAL_OPS: &[&str] = &["ret", "retf", "int3", "ud2", "hlt", "iret", "sysret", "sysretq"];
82	
83	/// Truth-producing instructions
84	const TRUTH_OPS: &[&str] = &["cmp", "test", "ucomiss", "ucomisd", "ucomis", "comisd", "comiss"];
85	
86	/// Classify an instruction into one of 12 IMASM glyphs
87	pub fn classify_instruction(ins: &Instruction) -> char {
88	    let mn = strip_prefix(&ins.mnemonic);
89	    let ops = ins.op_str.trim();
90	
91	    // Terminal instructions
92	    if mn.starts_with("ret") || TERMINAL_OPS.contains(&mn) {
93	        return TANCH;
94	    }
95	
96	    // call/jmp with direct vs indirect
97	    if mn == "call" {
98	        if is_direct(ops) {
99	            return AFWD;
100	        } else {
101	            return IMSCRIB;
102	        }
103	    }
104	
105	    if mn == "jmp" {
106	        if is_direct(ops) {
107	            return AREV;
108	        } else {
109	            return IMSCRIB;
110	        }
111	    }
112	
113	    // syscall
114	    if mn == "syscall" || (mn == "int" && ops == "0x80") {
115	        return IMSCRIB;
116	    }
117	
118	    // Conditional branches — forks (jcc except jmp)
119	    if mn.starts_with('j') && mn != "jmp" {
120	        return FSPLIT;
121	    }
122	
123	    // setcc — truth consumed
124	    if mn.starts_with("set") {
125	        return EVALF;
126	    }
127	
128	    // cmovcc — truth consumed
129	    if mn.starts_with("cmov") {
130	        return EVALF;
131	    }
132	
133	    // cmp/test
134	    if TRUTH_OPS.contains(&mn) {
135	        return EVALT;
136	    }
137	
138	    // Memory writes — commit state
139	    if writes_memory(ops) && !MOVE_OPS.contains(&mn) {
140	        return IFIX;
141	    }
142	
143	    // Data movement
144	    if MOVE_OPS.contains(&mn) {
145	        return CLINK;
146	    }
147	
148	    // Arithmetic/logic — engagement
149	    if ENGAGE_OPS.contains(&mn) {
150	        return ENGAGR;
151	    }
152	
153	    // Default: engagement (total mapping)
154	    ENGAGR
155	}
156	
157	/// An ordered address set. Instruction addresses arrive ascending, so lookup is
158	/// a binary search rather than a scan — a linear scan here makes `compute_merges`
159	/// quadratic, which is the difference between lifting a small object file and
160	/// lifting a real `.text`.
161	struct AddrSet {
162	    addrs: Vec<u64>,
163	}
164	
165	impl AddrSet {
166	    fn from_sorted(addrs: Vec<u64>) -> Self {
167	        AddrSet { addrs }
168	    }
169	
170	    fn contains(&self, addr: u64) -> bool {
171	        self.addrs.binary_search(&addr).is_ok()
172	    }
173	}
174	
175	/// Compute merge points: addresses with ≥2 predecessors
176	pub fn compute_merges(insns: &[Instruction]) -> Vec<u64> {
177	    let aset = AddrSet::from_sorted(insns.iter().map(|i| i.address).collect());
178	
179	    let mut preds: BTreeMap<u64, u32> = BTreeMap::new();
180	
181	    for idx in 0..insns.len() {
182	        let mn = strip_prefix(&insns[idx].mnemonic);
183	        let terminates = mn == "jmp" || mn.starts_with("ret");
184	
185	        // Fall-through edge
186	        if !terminates && idx + 1 < insns.len() {
187	            let target = insns[idx + 1].address;
188	            *preds.entry(target).or_insert(0) += 1;
189	        }
190	
191	        // Jump edge
192	        if mn.starts_with('j') {
193	            if let Some(t) = parse_imm(&insns[idx].op_str) {
194	                if aset.contains(t) {
195	                    *preds.entry(t).or_insert(0) += 1;
196	                }
197	            }
198	        }
199	    }
200	
201	    preds.into_iter().filter(|(_, c)| *c >= 2).map(|(a, _)| a).collect()
202	}
203	
204	/// Lift a function's instruction list to an IMASM word
205	pub fn recompile_function(insns: &[Instruction]) -> Vec<char> {
206	    // `compute_merges` returns ascending addresses, so membership is a binary
207	    // search. `Vec::contains` here would make the lift quadratic again.
208	    let merges = compute_merges(insns);
209	    let mut tokens = vec![VINIT];
210	
211	    for ins in insns {
212	        if merges.binary_search(&ins.address).is_ok() {
213	            tokens.push(FFUSE);
214	        }
215	        tokens.push(classify_instruction(ins));
216	    }
217	
218	    tokens
219	}
220	
221	/// Instructions a compiler uses to pad between functions.
222	pub const PAD_OPS: &[&str] = &["int3", "nop", "ud2"];
223	
224	/// Split a decoded run into functions.
225	///
226	/// A contiguous run of instructions is not one function. A boundary is a
227	/// terminal, then padding, then a body — all three, because both compilers
228	/// also pad for alignment inside a body and cutting on padding alone shatters
229	/// one function into dozens.
230	pub fn split_functions(insns: &[Instruction]) -> Vec<&[Instruction]> {
231	    let mut out = Vec::new();
232	    if insns.is_empty() {
233	        return out;
234	    }
235	    let mut start = 0usize;
236	    let mut saw_terminal = false;
237	    let mut in_pad = false;
238	
239	    for i in 1..insns.len() {
240	        let prev = strip_prefix(&insns[i - 1].mnemonic);
241	        let here = strip_prefix(&insns[i].mnemonic);
242	        if PAD_OPS.contains(&prev) {
243	            in_pad = true;
244	        } else if prev.starts_with("ret") || TERMINAL_OPS.contains(&prev) || prev == "jmp" {
245	            saw_terminal = true;
246	        } else {
247	            saw_terminal = false;
248	            in_pad = false;
249	        }
250	        if in_pad && saw_terminal && !PAD_OPS.contains(&here) {
251	            out.push(&insns[start..i]);
252	            start = i;
253	            saw_terminal = false;
254	            in_pad = false;
255	        }
256	    }
257	    out.push(&insns[start..]);
258	    // A stretch that is nothing but padding is not a function either.
259	    out.retain(|f| f.iter().any(|i| !PAD_OPS.contains(&strip_prefix(&i.mnemonic))));
260	    out
261	}
262	
263	/// Lift multiple functions to words
264	pub fn recompile_module(functions: &[(String, u64, Vec<Instruction>)]) -> Vec<(String, u64, Vec<char>)> {
265	    let mut result = Vec::new();
266	    for (label, addr, insns) in functions {
267	        let word = recompile_function(insns);
268	        result.push((label.clone(), *addr, word));
269	    }
270	    result
271	}
272	
273	/// Run SIXTEEN_3 verdict on an IMASM word.
274	///
275	/// T closes, B holds a fork open across a terminal, N never forked, and F is
276	/// not a truth value at all: it reports that the word is ill-typed, a ∋ with
277	/// no ∈ to pair. Refusing to score an ill-formed word is the point. A fuse
278	/// that nothing opened means the lifter cut a function in the wrong place, and
279	/// scoring it T or N would bury that under a verdict that looks like an answer.
280	/// Work opcodes: the seven that transform the object (⊞ is ENGAGR here, EVALI in the core: one glyph, two names). ∈ ∋ ⊙ ⊢ ⊣ do not.
281	fn is_work(g: char) -> bool { matches!(g, AFWD | AREV | CLINK | EVALT | EVALF | ENGAGR | IFIX) }
282	
283	/// Pair ∈ → ∋ over the word read as a loop.
284	///
285	/// A word is a loop and ROTAT is the cyclic shift, so any readout that pairs
286	/// split with fuse must pair around the cycle. Pairing over the linearized list
287	/// makes every region the cut passes through look dangling, and turns
288	/// rotation-invariant structure into spurious phase. Splits and fuses go
289	/// unmatched only on a true count imbalance, which no rotation can repair.
290	fn cyclic_pairs(word: &[char]) -> (Vec<(usize, usize)>, Vec<usize>, Vec<usize>) {
291	    let n = word.len();
292	    let split_idx: Vec<usize> = (0..n).filter(|&i| word[i] == FSPLIT).collect();
293	    let fuse_idx: Vec<usize> = (0..n).filter(|&i| word[i] == FFUSE).collect();
294	    if split_idx.is_empty() && fuse_idx.is_empty() { return (Vec::new(), Vec::new(), Vec::new()); }
295	    // Read from the index at which the running balance of splits against fuses
296	    // is least. From there the balance never falls below zero, so no fuse finds
297	    // the stack empty and the pairing is total on the smaller species: what is
298	    // left over is the surplus alone, and at most one side of it is non-empty.
299	    // On balanced counts this is the rotation that closes every region.
300	    let mut balance: i64 = 0;
301	    let mut least: i64 = 0;
302	    let mut start = 0usize;
303	    for i in 0..n {
304	        balance += if word[i] == FSPLIT { 1 } else if word[i] == FFUSE { -1 } else { 0 };
305	        if balance < least { least = balance; start = (i + 1) % n; }
306	    }
307	    let mut stack: Vec<usize> = Vec::new();
308	    let mut pairs: Vec<(usize, usize)> = Vec::new();
309	    let mut un_fuse: Vec<usize> = Vec::new();
310	    for off in 0..n {
311	        let i = (start + off) % n;
312	        if word[i] == FSPLIT { stack.push(i); }
313	        else if word[i] == FFUSE {
314	            match stack.pop() { Some(si) => pairs.push((si, i)), None => un_fuse.push(i) }
315	        }
316	    }
317	    stack.sort_unstable();
318	    un_fuse.sort_unstable();
319	    (pairs, stack, un_fuse)
320	}
321	
322	/// One region of a word's pairing: the division, the rejoining that answers it,
323	/// what stands between them, and whether any of that does work.
324	pub struct Region {
325	    pub split: usize,
326	    pub fuse: usize,
327	    pub interior: String,
328	    pub substantial: bool,
329	}
330	
331	/// The pairing of a word, reported. The regions in the order the reading forms
332	/// them, and the divisions and rejoinings the reading leaves unanswered.
333	pub fn pairing(word: &[char]) -> (Vec<Region>, Vec<usize>, Vec<usize>) {
334	    let (pairs, un_split, un_fuse) = cyclic_pairs(word);
335	    let regions = pairs.into_iter().map(|(si, fj)| {
336	        let inner = cyclic_interior(word, si, fj);
337	        Region {
338	            split: si,
339	            fuse: fj,
340	            substantial: inner.iter().copied().any(is_work),
341	            interior: inner.into_iter().collect(),
342	        }
343	    }).collect();
344	    (regions, un_split, un_fuse)
345	}
346	
347	/// Glyphs strictly inside a region, walking forward around the cycle.
348	fn cyclic_interior(word: &[char], si: usize, fj: usize) -> Vec<char> {
349	    let n = word.len();
350	    let len = (fj + n - si - 1) % n;
351	    (0..len).map(|j| word[(si + 1 + j) % n]).collect()
352	}
353	
354	/// The tri-ancestral verdict, the same rule the SIXTEEN_3 engine reads.
355	///
356	/// T — every ∈ pairs with a ∋ around the cycle, and at least one work opcode
357	///     ran inside that region (a real transformation).
358	/// N — split and fused, but no work ran inside: μ∘δ=id verifies nothing. Also
359	///     the void, where nothing ever forked.
360	/// B — an ∈ dangles with no ∋ to pair (a fork left open).
361	/// F — a ∋ has no ∈ to pair (ill-typed).
362	pub fn verdict(word: &[char]) -> char {
363	    let (pairs, un_split, un_fuse) = cyclic_pairs(word);
364	    if pairs.is_empty() && un_split.is_empty() && un_fuse.is_empty() { return 'N'; }
365	    if un_fuse.len() > un_split.len() { return 'F'; }
366	    if !un_split.is_empty() { return 'B'; }
367	    for (si, fj) in pairs {
368	        if cyclic_interior(word, si, fj).into_iter().any(is_work) { return 'T'; }
369	    }
370	    'N'
371	}
372	
373	
374	/// What a word's open forks are, split into the part exits explain and the part
375	/// they do not.
376	///
377	/// A held-open fork is not by itself a defect. An early return IS a fork that
378	/// leaves and never rejoins, so a function with several exits carries several
379	/// open forks by construction. Measured across a large real binary the surplus
380	/// of ∈ over ∋ rises with the number of terminals at about five per exit, from
381	/// a mean of 0.30 at one exit to 15.5 at four or more, and above two exits
382	/// essentially every function carries surplus. Ranking candidates by raw
383	/// surplus therefore ranks by how many ways a function can return.
384	///
385	/// The residual is what remains once exits are accounted for. That is the part
386	/// worth reading.
387	pub struct OpenForks {
388	    /// ∈ minus ∋: forks the word never closes
389	    pub surplus: i32,
390	    /// ⊣ in the word: the ways this function leaves
391	    pub exits: i32,
392	    /// surplus beyond what the exits explain
393	    pub residual: i32,
394	}
395	
396	/// Slope of surplus against exit count, measured over a stripped release binary
397	/// of about fifteen hundred functions.
398	const SURPLUS_PER_EXIT: i32 = 5;
399	
400	pub fn open_forks(word: &[char]) -> OpenForks {
401	    let splits = word.iter().filter(|&&c| c == FSPLIT).count() as i32;
402	    let fuses  = word.iter().filter(|&&c| c == FFUSE).count() as i32;
403	    let exits  = word.iter().filter(|&&c| c == TANCH).count() as i32;
404	    let surplus = splits - fuses;
405	    OpenForks { surplus, exits, residual: surplus - SURPLUS_PER_EXIT * exits }
406	}
407	
408	/// Emit word as glyph string
409	pub fn glyphs(word: &[char]) -> String {
410	    word.iter().collect()
411	}
412	
413	/// Emit IMASM module text for a set of functions
414	pub fn emit_word(functions: &[(&str, u64, &[Instruction])]) -> String {
415	    let mut lines = vec![format!("; ⊙ vox native module")];
416	    let total: usize = functions.iter().map(|f| recompile_function(f.2).len()).sum();
417	    lines.push(format!("; {} words   {} glyphs", functions.len(), total));
418	    for (_label, addr, insns) in functions {
419	        let word = recompile_function(insns);
420	        lines.push(format!("0x{:x}", addr));
421	        lines.push(glyphs(&word));
422	    }
423	    lines.join("\n") + "\n"
424	}
425	
426	/// Check round-trip: lift(decompile(emit(binary))) == lift(recompile_module(binary))
427	pub fn roundtrip_check(functions: &[(String, u64, Vec<Instruction>)]) -> bool {
428	    let words1 = recompile_module(functions);
429	    let mut combined1 = String::new();
430	    for (_, _, w) in &words1 {
431	        for c in w {
432	            combined1.push(*c);
433	        }
434	    }
435	
436	    // Re-emit and parse back
437	    let views: Vec<(&str, u64, &[Instruction])> = functions.iter()
438	        .map(|(l, a, ins)| (l.as_str(), *a, ins.as_slice()))
439	        .collect();
440	    let text = emit_word(&views);
441	    let mut combined2 = String::new();
442	    for line in text.lines() {
443	        if line.starts_with('0') || line.is_empty() || line.starts_with(';') {
444	            continue;
445	        }
446	        combined2.push_str(line);
447	    }
448	
449	    combined1 == combined2
450	}
451	
452	/// Every defined function address in an ELF's symbol tables.
453	///
454	/// A shared object's own entry point calls almost none of its exported
455	/// functions — those are called from outside, by whoever loads it — so descent
456	/// from the entry alone misses them. Seeding every defined function symbol is
457	/// what turns a handful of reachable functions into the whole program.
458	pub fn elf_function_symbols(raw: &[u8]) -> Vec<u64> {
459	    let mut out = Vec::new();
460	    if raw.len() < 64 || &raw[0..4] != b"\x7fELF" || raw[4] != 2 {
461	        return out;
462	    }
463	    let rd64 = |o: usize| -> u64 {
464	        u64::from_le_bytes(raw[o..o + 8].try_into().unwrap_or([0; 8]))
465	    };
466	    let rd32 = |o: usize| -> u32 {
467	        u32::from_le_bytes(raw[o..o + 4].try_into().unwrap_or([0; 4]))
468	    };
469	    let rd16 = |o: usize| -> u16 {
470	        u16::from_le_bytes(raw[o..o + 2].try_into().unwrap_or([0; 2]))
471	    };
472	    let shoff = rd64(40) as usize;
473	    let shentsize = rd16(58) as usize;
474	    let shnum = rd16(60) as usize;
475	    for k in 0..shnum {
476	        let sh = shoff + k * shentsize;
477	        if sh + 64 > raw.len() {
478	            break;
479	        }
480	        let sh_type = rd32(sh + 4);
481	        // SHT_SYMTAB = 2, SHT_DYNSYM = 11
482	        if sh_type != 2 && sh_type != 11 {
483	            continue;
484	        }
485	        let off = rd64(sh + 24) as usize;
486	        let size = rd64(sh + 32) as usize;
487	        let entsize = rd64(sh + 56) as usize;
488	        if entsize == 0 || off + size > raw.len() {
489	            continue;
490	        }
491	        let mut e = off;
492	        while e + entsize <= off + size {
493	            let info = raw[e + 4];
494	            let value = rd64(e + 8);
495	            // STT_FUNC = 2 in the low nibble of st_info
496	            if info & 0x0F == 2 && value != 0 {
497	                out.push(value);
498	            }
499	            e += entsize;
500	        }
501	    }
502	    out.sort_unstable();
503	    out.dedup();
504	    out
505	}
506	
507	/// Parse ELF binary to extract executable sections
508	pub fn parse_elf(raw: &[u8]) -> (u64, Vec<(u64, Vec<u8>)>) {
509	    if raw.len() < 64 || &raw[0..4] != b"\x7fELF" {
510	        return (0, vec![]);
511	    }
512	
513	    let is_64 = raw[4] == 2;
514	    let is_le = raw[5] == 1;
515	
516	    // Helper closures for reading little/big endian
517	    let read_u64 = |off: usize| -> u64 {
518	        if is_le {
519	            u64::from_le_bytes(raw[off..off+8].try_into().unwrap())
520	        } else {
521	            u64::from_be_bytes(raw[off..off+8].try_into().unwrap())
522	        }
523	    };
524	
525	    let read_u32 = |off: usize| -> u32 {
526	        if is_le {
527	            u32::from_le_bytes(raw[off..off+4].try_into().unwrap())
528	        } else {
529	            u32::from_be_bytes(raw[off..off+4].try_into().unwrap())
530	        }
531	    };
532	
533	    let read_u16 = |off: usize| -> u16 {
534	        if is_le {
535	            u16::from_le_bytes(raw[off..off+2].try_into().unwrap())
536	        } else {
537	            u16::from_be_bytes(raw[off..off+2].try_into().unwrap())
538	        }
539	    };
540	
541	    let (entry, shoff, shentsize, shnum) = if is_64 {
542	        (read_u64(24), read_u64(40), read_u16(58), read_u16(60))
543	    } else {
544	        (read_u32(24) as u64, read_u32(32) as u64, read_u16(46), read_u16(48))
545	    };
546	
547	    let mut segments = vec![];
548	
549	    for k in 0..shnum {
550	        let off = (shoff + (k as u64) * (shentsize as u64)) as usize;
551	        if off >= raw.len() { break; }
552	
553	        if is_64 {
554	            // ELF64 section header: sh_name(4) at +0, sh_type(4) at +4,
555	            // sh_flags(8) at +8, sh_addr(8) at +16, sh_offset(8) at +24,
556	            // sh_size(8) at +32. Reading sh_type at +0 picks up sh_name and
557	            // nothing ever matches SHT_PROGBITS.
558	            let sh_type = read_u32(off + 4);
559	            let sh_flags = read_u64(off + 8);
560	            let sh_addr = read_u64(off + 16);
561	            let sh_offset = read_u64(off + 24);
562	            let sh_size = read_u64(off + 32);
563	
564	            // SHT_PROGBITS=1, SHF_EXECINSTR=0x4
565	            if sh_type == 1 && (sh_flags & 0x4) != 0 && sh_size > 0 {
566	                let end = (sh_offset + sh_size) as usize;
567	                if end <= raw.len() {
568	                    segments.push((sh_addr, raw[sh_offset as usize..end].to_vec()));
569	                }
570	            }
571	        } else {
572	            // ELF32 section header: sh_name(4), sh_type(4), sh_flags(4),
573	            // sh_addr(4), sh_offset(4), sh_size(4).
574	            let sh_type = read_u32(off + 4);
575	            let sh_flags = read_u32(off + 8) as u64;
576	            let sh_addr = read_u32(off + 12) as u64;
577	            let sh_offset = read_u32(off + 16) as u64;
578	            let sh_size = read_u32(off + 20) as u64;
579	
580	            if sh_type == 1 && (sh_flags & 0x4) != 0 && sh_size > 0 {
581	                let end = (sh_offset + sh_size) as usize;
582	                if end <= raw.len() {
583	                    segments.push((sh_addr, raw[sh_offset as usize..end].to_vec()));
584	                }
585	            }
586	        }
587	    }
588	
589	    (entry, segments)
590	}
