1	//! The module format: a word in the twelve, and the executable payload each
2	//! glyph carries. Ported from imasm_module.py. The glyph is the opcode (which of
3	//! the twelve axes the instruction is); the payload is normalised operands the
4	//! machine reads without ever parsing assembly.
5	//!
6	//! ```text
7	//! GLYPH \t field \t field ...      with  r:reg  i:imm  m:base:index:scale:disp:size
8	//! ```
9	
10	use alloc::string::{String, ToString};
11	use alloc::vec::Vec;
12	use alloc::collections::{BTreeMap, BTreeSet};
13	use alloc::format;
14	
15	use crate::x86::{self, Op};
16	use crate::vox_decode;
17	use crate::loader;
18	
19	fn bits_of(arch: &str) -> u8 { if arch == "x86-32" { 32 } else { 64 } }
20	
21	const ENTRY: char = '⊢'; const TERM: char = '⊣'; const SPLIT: char = '∈'; const FUSE: char = '∋';
22	const CALL: char = '≻'; const XFER: char = '≺'; const INDIRECT: char = '⊙'; const COMMIT: char = '⊡';
23	const LINK: char = '⋈'; const TRUTH: char = '⊤'; const CONSUME: char = '⊥'; const ENGAGE: char = '⊞';
24	
25	fn is_move(mn: &str) -> bool {
26	    matches!(mn, "mov"|"movzx"|"movsx"|"movsxd"|"movabs"|"push"|"pop"|"xchg"|"leave")
27	}
28	fn is_truth(mn: &str) -> bool { matches!(mn, "cmp"|"test") }
29	fn is_terminal(mn: &str) -> bool { mn.starts_with("ret") || matches!(mn, "int3"|"ud2"|"hlt"|"iret"|"retf") }
30	
31	/// The glyph — the same decision vox's classifier makes.
32	pub fn classify(i: &x86::Insn) -> char {
