63	impl Machine {
64	    pub fn new(module: &str) -> Machine {
65	        let mut m = Machine {
66	            code: BTreeMap::new(), addrs: Vec::new(), next_of: BTreeMap::new(), entry: 0,
67	            reg: BTreeMap::new(), mem: BTreeMap::new(), flags: (0,0,1), kind: "cmp".into(), steps: 0, bits: 64,
68	        };
69	        for r in ["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15","rip"] {
70	            m.reg.insert(r.into(), 0);
71	        }
72	        for k in 0..16 { m.reg.insert(format!("xmm{}", k), 0); }
73	        m.reg.insert("rsp".into(), 0x7FFF_0000);
74	        m.parse(module);
75	        m
76	    }
