78	    fn parse(&mut self, text: &str) {
79	        let mut addr: Option<u64> = None;
80	        for line in text.lines() {
81	            if let Some(rest) = line.strip_prefix(';') {
82	                let t = rest.trim();
83	                if let Some(e) = t.strip_prefix("entry ") {
84	                    if let Ok(v) = u64::from_str_radix(e.trim().trim_start_matches("0x"), 16) { self.entry = v; }
85	                } else if let Some(b) = t.strip_prefix("bits ") {
86	                    if let Ok(v) = b.trim().parse::<u8>() { self.bits = v; }
87	                }
88	            } else if let Some(rest) = line.strip_prefix('=') {
89	                let mut it = rest.splitn(2, '\t');
90	                if let (Some(at), Some(blob)) = (it.next(), it.next()) {
91	                    if let Ok(a) = u64::from_str_radix(at.trim().trim_start_matches("0x"), 16) {
92	                        let bytes = hexbytes(blob);
93	                        for (k, b) in bytes.iter().enumerate() { if *b != 0 { self.mem.insert(a + k as u64, *b); } }
94	                    }
95	                }
96	            } else if let Some(rest) = line.strip_prefix('@') {
97	                if let Ok(a) = u64::from_str_radix(rest.trim().trim_start_matches("0x"), 16) {
98	                    addr = Some(a); self.code.entry(a).or_default();
99	                }
100	            } else if !line.is_empty() {
101	                if let Some(a) = addr {
102	                    let mut parts = line.split('\t');
103	                    if let Some(g) = parts.next() {
104	                        let glyph = g.chars().next().unwrap_or('?');
105	                        let fields: Vec<String> = parts.map(|s| s.to_string()).collect();
106	                        self.code.get_mut(&a).unwrap().push((glyph, fields));
107	                    }
108	                }
109	            }
110	        }
111	        self.addrs = self.code.keys().copied().collect();
112	        for w in self.addrs.windows(2) { self.next_of.insert(w[0], w[1]); }
113	    }
114	
115	    // ── slots ──
116	    fn get_reg(&self, name: &str) -> u128 {
117	        let (base, size, off) = reg_info(name);
118	        (self.reg[base] >> (off as u32 * 8)) & mask(size)
119	    }
120	    fn set_reg(&mut self, name: &str, val: u128) {
121	        let (base, size, off) = reg_info(name);
122	        let cur = self.reg.get(base).copied().unwrap_or(0);
123	        let nv = match size {
124	            8 => val & mask(8),
125	            4 => val & mask(4),           // 32-bit writes zero the top
126	            16 => val & mask(16),
127	            _ => { let m = mask(size) << (off as u32 * 8); (cur & !m) | ((val << (off as u32 * 8)) & m) }
128	        };
129	        self.reg.insert(base.to_string(), nv);
130	    }
131	    fn load(&self, addr: u64, size: u8) -> u128 {
132	        let mut v = 0u128;
133	        for k in 0..size as u64 { v |= (*self.mem.get(&(addr + k)).unwrap_or(&0) as u128) << (8 * k); }
134	        v
135	    }
136	    fn store(&mut self, addr: u64, val: u128, size: u8) {
137	        let v = val & mask(size);
138	        for k in 0..size as u64 { self.mem.insert(addr + k, ((v >> (8*k)) & 0xFF) as u8); }
139	    }
140	    fn ea(&self, field: &str) -> (u64, u8) {
141	        // m:base:index:scale:disp:size
142	        let parts: Vec<&str> = field.split(':').collect();
143	        let base = parts[1]; let index = parts[2]; let scale = parts[3];
144	        let disp = parts[4]; let size: u8 = parts[5].parse().unwrap_or(8);
145	        let mut a: i128 = if !base.is_empty() { self.get_reg(base) as i128 } else { 0 };
146	        if !index.is_empty() { a += self.get_reg(index) as i128 * scale.parse::<i128>().unwrap_or(1); }
147	        a += parse_imm(disp);
148	        ((a as u128 & mask(8)) as u64, size)
149	    }
150	    fn read(&self, field: &str, size_hint: u8) -> (u128, u8) {
151	        match field.as_bytes()[0] {
152	            b'r' => { let n = &field[2..]; (self.get_reg(n), reg_info(n).1) }
153	            b'i' => ((parse_imm(&field[2..]) as u128) & mask(8), size_hint),
154	            _ => { let (a, s) = self.ea(field); (self.load(a, s), s) }
155	        }
156	    }
157	    fn write(&mut self, field: &str, val: u128) {
158	        if field.as_bytes()[0] == b'r' { self.set_reg(&field[2..], val); }
159	        else { let (a, s) = self.ea(field); self.store(a, val, s); }
160	    }
161	    fn width(&self, field: &str) -> u8 {
162	        match field.as_bytes()[0] {
163	            b'r' => reg_info(&field[2..]).1,
164	            b'm' => field.rsplit(':').next().and_then(|s| s.parse().ok()).unwrap_or(8),
165	            _ => 8,
166	        }
167	    }
168	
169	    // ── truth ──
170	    fn cc(&self, name: &str) -> bool {
171	        let (a, b, size) = self.flags;
172	        let (zf, sf, cf, of);
173	        if self.kind == "test" {
174	            let r = (a & b) & mask(size);
175	            zf = r == 0; sf = sign(r, size) < 0; cf = false; of = false;
176	        } else {
177	            let r = a.wrapping_sub(b) & mask(size);
178	            zf = r == 0; sf = sign(r, size) < 0;
179	            cf = (a & mask(size)) < (b & mask(size));
180	            of = (sign(a, size) - sign(b, size)) != sign(r, size);
181	        }
182	        match name {
183	            "e"|"z" => zf, "ne"|"nz" => !zf,
184	            "s" => sf, "ns" => !sf,
185	            "b"|"nae"|"c" => cf, "ae"|"nb"|"nc" => !cf,
186	            "be"|"na" => cf||zf, "a"|"nbe" => !(cf||zf),
187	            "l"|"nge" => sf!=of, "ge"|"nl" => sf==of,
188	            "le"|"ng" => zf||(sf!=of), "g"|"nle" => !zf&&sf==of,
189	            "o" => of, "no" => !of, "p" => false, "np" => true,
190	            _ => false,
191	        }
192	    }
193	    fn set_flags(&mut self, a: u128, b: u128, size: u8, kind: &str) { self.flags = (a, b, size); self.kind = kind.to_string(); }
194	
195	    fn slot(&self) -> u8 { self.bits / 8 }              // stack slot width, 8 or 4
196	    fn push_val(&mut self, v: u128) { let s = self.slot(); self.set_reg("rsp", self.get_reg("rsp").wrapping_sub(s as u128)); let sp = self.get_reg("rsp") as u64; self.store(sp, v, s); }
197	    fn pop_val(&mut self) -> u128 { let s = self.slot(); let sp = self.get_reg("rsp") as u64; let v = self.load(sp, s); self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); v }
198	
199	    fn do_syscall(&mut self) -> Result<(), Stop> {
200	        let num = sign(self.get_reg("rax"), 8);
201	        let a0 = self.get_reg("rdi"); let _a1 = self.get_reg("rsi"); let _a2 = self.get_reg("rdx");
202	        if num == 60 || num == 231 { return Err(Stop::SysExit((sign(a0,8) & 0xFF) as i32)); }
203	        // write and others: this is a function tester; anything but exit returns -ENOSYS
204	        self.set_reg("rax", (-38i128 as u128) & mask(8));
205	        Ok(())
206	    }
207	
208	    // ── ALU ──
209	    fn alu(&mut self, op: &str, f: &[String]) {
210	        match op {
211	            "nop"|"endbr64"|"endbr32" => return,
212	            "lea" => { let (a,_) = self.ea(&f[1]); self.write(&f[0], a as u128); return; }
213	            "cdq"|"cltd" => { let v = if sign(self.get_reg("eax"),4) < 0 { mask(4) } else { 0 }; self.set_reg("edx", v); return; }
214	            "cqo" => { let v = if sign(self.get_reg("rax"),8) < 0 { mask(8) } else { 0 }; self.set_reg("rdx", v); return; }
215	            "cdqe"|"cltq" => { let v = (sign(self.get_reg("eax"),4) as u128) & mask(8); self.set_reg("rax", v); return; }
216	            "idiv"|"div" => {
217	                let size = self.width(&f[0]);
218	                let d = self.read(&f[0], size).0;
219	                let (lo_n, hi_n) = ([8u8,4,2,1].contains(&size), true); let _ = (lo_n, hi_n);
220	                let lo = self.get_reg(match size {8=>"rax",4=>"eax",2=>"ax",_=>"al"});
221	                let hi = self.get_reg(match size {8=>"rdx",4=>"edx",2=>"dx",_=>"ah"});
222	                let (q, r);
223	                if op == "idiv" {
224	                    let n = sign((hi << (size as u32 *8)) | lo, if size < 8 { size*2 } else { 8 });
225	                    let dd = sign(d, size);
226	                    let qq = (n.abs() / dd.abs()) * if (n<0)==(dd<0) {1} else {-1};
227	                    q = (qq as u128) & mask(size); r = ((n - qq*dd) as u128) & mask(size);
228	                } else {
229	                    let n = (hi << (size as u32 *8)) | lo;
230	                    q = (n / d) & mask(size); r = (n % d) & mask(size);
231	                }
232	                self.set_reg(match size {8=>"rax",4=>"eax",2=>"ax",_=>"al"}, q);
233	                self.set_reg(match size {8=>"rdx",4=>"edx",2=>"dx",_=>"ah"}, r);
234	                return;
235	            }
236	            _ => {}
237	        }
238	        if is_simd(op) { self.simd(op, f); return; }
239	
240	        let size = self.width(&f[0]);
241	        let a = self.read(&f[0], size).0;
242	        if matches!(op, "not"|"neg"|"inc"|"dec") {
243	            let r = match op { "not" => !a, "neg" => (a as i128).wrapping_neg() as u128, "inc" => a.wrapping_add(1), _ => a.wrapping_sub(1) };
244	            self.write(&f[0], r & mask(size));
245	            if op != "not" { self.set_flags(r & mask(size), 0, size, "cmp"); }
246	            return;
247	        }
248	        // One-operand imul/mul: the full 2*size product lands in edx:eax
249	        // (rdx:rax at 64-bit). Dropping the high half silently breaks every
250	        // magic-number division the compiler emits.
251	        if (op == "imul" || op == "mul") && f.len() == 1 {
252	            let (lo_r, hi_r) = match size { 8 => ("rax","rdx"), 4 => ("eax","edx"), 2 => ("ax","dx"), _ => ("al","ah") };
253	            let prod: u128 = if op == "imul" {
254	                ((sign(self.get_reg(lo_r), size)).wrapping_mul(sign(a, size))) as u128
255	            } else {
256	                (self.get_reg(lo_r) & mask(size)).wrapping_mul(a & mask(size))
257	            };
258	            self.set_reg(lo_r, prod & mask(size));
259	            let hi = (prod >> (size as u32 * 8)) & mask(size);
260	            self.set_reg(hi_r, hi);
261	            self.set_flags(prod & mask(size), 0, size, "cmp");
262	            return;
263	        }
264	        if op == "imul" && f.len() == 3 {
265	            let x = self.read(&f[1], size).0; let y = self.read(&f[2], size).0;
266	            let r = (sign(x, size) * sign(y, size)) as u128;
267	            self.write(&f[0], r & mask(size));
268	            self.set_flags(r & mask(size), 0, size, "cmp");
269	            return;
270	        }
271	        let b = self.read(&f[f.len()-1], size).0;
272	        let r: u128 = match op {
273	            "add"|"adc" => a.wrapping_add(b),
274	            "sub"|"sbb" => a.wrapping_sub(b),
275	            "and" => a & b, "or" => a | b, "xor" => a ^ b,
276	            "imul" => (sign(a,size) * sign(b,size)) as u128,
277	            "shl"|"sal" => a.wrapping_shl((b & 63) as u32),
278	            "shr" => (a & mask(size)) >> (b & 63),
279	            "sar" => (sign(a,size) >> (b & 63)) as u128,
280	            _ => a,
281	        };
282	        self.write(&f[0], r & mask(size));
283	        self.set_flags(r & mask(size), 0, size, "cmp");
284	    }
285	
286	    fn simd(&mut self, op: &str, f: &[String]) {
287	        let dst = f[0].clone();
288	        match op {
289	            "movdqa"|"movdqu"|"movaps"|"movups" => { let v = self.read(&f[1], 16).0; self.write(&dst, v & mask(16)); }
290	            "movd"|"movq" => {
291	                let w = if op == "movd" { 4 } else { 8 };
292	                let src_is_x = f[1].starts_with("r:xmm");
293	                let v = self.read(&f[1], w).0;
294	                if dst.starts_with("r:xmm") { self.write(&dst, v & mask(w)); }
295	                else { self.write(&dst, if src_is_x { v & mask(w) } else { v }); }
296	            }
297	            "psrldq" => { let a = self.read(&dst,16).0; let n = parse_imm(&f[1][2..]) as u32; self.write(&dst, (a >> (n*8)) & mask(16)); }
298	            "psrlq"|"psllq" => {
299	                let a = self.read(&dst,16).0;
300	                let n = if f[1].as_bytes()[0]==b'i' { parse_imm(&f[1][2..]) as u32 } else { self.read(&f[1],8).0 as u32 };
301	                let lanes = [ (a & mask(8)), (a >> 64) & mask(8) ];
302	                let r: [u128;2] = if op=="psrlq" { [lanes[0]>>n, lanes[1]>>n] } else { [(lanes[0]<<n)&mask(8), (lanes[1]<<n)&mask(8)] };
303	                self.write(&dst, r[0] | (r[1] << 64));
304	            }
305	            "pshufd" => {
306	                let a = self.read(&f[1],16).0; let sel = parse_imm(&f[2][2..]) as u128;
307	                let l = [a&mask(4),(a>>32)&mask(4),(a>>64)&mask(4),(a>>96)&mask(4)];
308	                let mut o=0u128; for k in 0..4 { let s=((sel>>(2*k))&3) as usize; o |= l[s] << (32*k); }
309	                self.write(&dst, o);
310	            }
311	            "punpcklqdq" => { let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0; self.write(&dst, (a&mask(8))|((b&mask(8))<<64)); }
312	            "punpckldq" => {
313	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
314	                let x=[a&mask(4),(a>>32)&mask(4)]; let y=[b&mask(4),(b>>32)&mask(4)];
315	                self.write(&dst, x[0] | (y[0]<<32) | (x[1]<<64) | (y[1]<<96));
316	            }
317	            "pmuludq" => {
318	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
319	                let x0=a&mask(4); let x2=(a>>64)&mask(4); let y0=b&mask(4); let y2=(b>>64)&mask(4);
320	                self.write(&dst, (x0*y0) | ((x2*y2)<<64));
321	            }
322	            "pxor"|"pand"|"por" => { let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
323	                self.write(&dst, match op {"pxor"=>a^b,"pand"=>a&b,_=>a|b}); }
324	            _ => { // lane-wise padd/psub/pmull
325	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
326	                let w: u8 = match op.chars().last().unwrap() {'b'=>1,'w'=>2,'d'=>4,'q'=>8,_=>4};
327	                let n = 16 / w; let mut o=0u128;
328	                for k in 0..n {
329	                    let sh = (k*w) as u32 * 8;
330	                    let p = (a >> sh) & mask(w); let q = (b >> sh) & mask(w);
331	                    let v = if op.starts_with("padd") { p.wrapping_add(q) } else if op.starts_with("psub") { p.wrapping_sub(q) } else { p.wrapping_mul(q) };
332	                    o |= (v & mask(w)) << sh;
333	                }
334	                self.write(&dst, o);
335	            }
336	        }
337	    }
338	
339	    fn step(&mut self, addr: u64) -> Result<Option<u64>, Stop> {
340	        let next = self.next_of.get(&addr).copied().unwrap_or(0);
341	        self.reg.insert("rip".into(), next as u128);
342	        let insns = self.code.get(&addr).cloned().unwrap_or_default();
343	        for (glyph, f) in insns {
344	            match glyph {
345	                '∋' => continue,
346	                '⊣' => {
347	                    if f.get(0).map(|s| s.as_str()) == Some("leave") {
348	                        let s = self.slot();
349	                        let rbp = self.get_reg("rbp"); self.set_reg("rsp", rbp);
350	                        let v = self.load(self.get_reg("rsp") as u64, s); self.set_reg("rbp", v);
351	                        self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); continue;
352	                    }
353	                    let ret = self.pop_val();
354	                    // ret imm16: stdcall callee-cleanup of stack args.
355	                    if let Some(im) = f.get(1) { if im.as_bytes().get(0) == Some(&b'i') {
356	                        let n = parse_imm(&im[2..]) as u128;
357	                        self.set_reg("rsp", self.get_reg("rsp").wrapping_add(n));
358	                    }}
359	                    return Ok(Some(ret as u64));
360	                }
361	                '⊤' => { let size=self.width(&f[1]); let a=self.read(&f[1],size).0; let b=self.read(&f[2],size).0; self.set_flags(a,b,size,&f[0]); }
362	                '∈' => { if self.cc(&f[0]) { return Ok(Some(parse_imm(&f[1][2..]) as u64)); } }
363	                '≺' => { return Ok(Some(parse_imm(&f[1][2..]) as u64)); }
364	                '⊙' => {
365	                    if f.get(0).map(|s|s.as_str()) == Some("syscall") { self.do_syscall()?; continue; }
366	                    if f.get(0).map(|s|s.as_str()) == Some("external") { return Err(Stop::Halt(format!("external {}", f.get(1).cloned().unwrap_or_default()))); }
367	                    let tgt = self.read(&f[1], 8).0;
368	                    if f.get(0).map(|s|s.as_str()) == Some("call") { self.push_val(next as u128); }
369	                    return Ok(Some(tgt as u64));
370	                }
371	                '≻' => {
372	                    self.push_val(next as u128);
373	                    return Ok(Some(parse_imm(&f[1][2..]) as u64));
374	                }
375	                '⋈' | '⊡' => {
376	                    let op = f[0].as_str();
377	                    match op {
378	                        "push" => { let v=self.read(&f[1],self.slot()).0; self.push_val(v); }
379	                        "pop" => { let v=self.pop_val(); self.write(&f[1], v); }
380	                        "leave" => { let s=self.slot(); let rbp=self.get_reg("rbp"); self.set_reg("rsp",rbp); let v=self.load(self.get_reg("rsp") as u64,s); self.set_reg("rbp",v); self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); }
381	                        "xchg" => { let x=self.read(&f[1],8).0; let y=self.read(&f[2],8).0; self.write(&f[1],y); self.write(&f[2],x); }
382	                        "mov"|"movabs" => { let w=self.width(&f[1]); let v=self.read(&f[2],w).0; self.write(&f[1], v & mask(w)); }
383	                        "movzx" => { let v=self.read(&f[2],8).0; self.write(&f[1], v & mask(self.width(&f[2]))); }
384	                        "movsx"|"movsxd" => { let sw=self.width(&f[2]); let v=self.read(&f[2],8).0; self.write(&f[1], (sign(v,sw) as u128) & mask(self.width(&f[1]))); }
385	                        _ => self.alu(op, &f[1..]),
386	                    }
387	                }
388	                '⊥' => {
389	                    if f.get(1).map(|s|s.as_str()) == Some("set") { let v = if self.cc(&f[0]) {1} else {0}; self.write(&f[2], v); }
390	                    else if self.cc(&f[0]) { let w=self.width(&f[2]); let v=self.read(&f[3],w).0; self.write(&f[2], v); }
391	                }
392	                '⊞' => self.alu(&f[0], &f[1..]),
393	                _ => {}
394	            }
395	        }
396	        Ok(self.next_of.get(&addr).copied())
397	    }
398	
399	    /// Run one function to its ⊣. 64-bit takes integer args in registers (System
400	    /// V); 32-bit takes them on the stack (cdecl). Returns eax.
401	    pub fn call(&mut self, addr: u64, args: &[i64], limit: u64) -> Result<i64, Stop> {
402	        let sentinel: u64 = 0xDEAD_0000;
403	        if self.bits == 32 {
404	            // cdecl: args pushed right-to-left, then the return address on top.
405	            for v in args.iter().rev() { self.push_val((*v as u32) as u128); }
406	            self.push_val(sentinel as u128);
407	        } else {
408	            for (name, v) in ["rdi","rsi","rdx","rcx","r8","r9"].iter().zip(args) {
409	                self.set_reg(name, (*v as u128) & mask(8));
410	            }
411	            self.push_val(sentinel as u128);
412	        }
413	        let mut pc = addr; self.steps = 0;
414	        let mut trace: Vec<String> = Vec::new();
415	        while pc != sentinel {
416	            if !self.code.contains_key(&pc) {
417	                return Err(Stop::Halt(format!("no instruction at 0x{:x} after {} steps\n  previous 12:\n{}", pc, self.steps, trace.join("\n"))));
418	            }
419	            if trace.len() >= 12 { trace.remove(0); }
420	            let insn_txt = self.code.get(&pc).map(|v| v.iter().map(|(g,f)| format!("{} {}", g, f.join(" "))).collect::<Vec<_>>().join(" ; ")).unwrap_or_default();
421	            trace.push(format!("  {:04x}: {}", pc, insn_txt));
422	            match self.step(pc)? {
423	                Some(n) => pc = n,
424	                None => return Err(Stop::Halt(format!("ran off the end after {} steps\n  previous 12:\n{}", self.steps, trace.join("\n")))),
425	            }
426	            self.steps += 1;
427	            if self.steps > limit { return Err(Stop::Halt(format!("ran off the end after {} steps", self.steps))); }
428	        }
429	        Ok(sign(self.get_reg("eax"), 4) as i64)
430	    }
431	}
432	
433	fn is_simd(op: &str) -> bool {
434	    matches!(op, "movdqa"|"movdqu"|"movaps"|"movups"|"movd"|"movq"|"pxor"|"pand"|"por"
435	        |"paddd"|"paddq"|"paddw"|"paddb"|"psubd"|"psubq"|"psubw"|"psubb"|"pmulld"|"pmuludq"
436	        |"psrlq"|"psllq"|"psrldq"|"pshufd"|"punpckldq"|"punpcklqdq")
437	}
438	
439	fn hexbytes(s: &str) -> Vec<u8> {
440	    let mut out = Vec::new(); let mut hi: Option<u8> = None;
441	    for ch in s.chars() {
442	        let v = match ch { '0'..='9'=>ch as u8-b'0','a'..='f'=>ch as u8-b'a'+10,'A'..='F'=>ch as u8-b'A'+10,_=>continue };
443	        match hi { None=>hi=Some(v), Some(h)=>{ out.push((h<<4)|v); hi=None; } }
444	    }
445	    out
446	}
447	
448	/// Parse an immediate spelled "0x1a" or "-0x1a".
449	fn parse_imm(s: &str) -> i128 {
450	    let s = s.trim();
451	    if let Some(rest) = s.strip_prefix('-') {
452	        -(i128::from_str_radix(rest.trim_start_matches("0x"), 16).unwrap_or(0))
453	    } else {
454	        i128::from_str_radix(s.trim_start_matches("0x"), 16).unwrap_or(0)
455	    }
456	}
