1	//! Universal executable loader: ELF, PE, Mach-O (including fat), and a raw
2	//! fallback. The x86 decoder and the machine are format-agnostic; they take
3	//! code segments and data segments. This is the one place a file's container is
4	//! read, so every format arrives at the same pipeline: (entry, code, data).
5	//!
6	//! The container is universal; the instruction set is x86-64. A code segment
7	//! that is not x86 simply fails to decode, instruction by instruction, and the
8	//! walk reports how far it got, rather than being refused up front.
9	
10	use alloc::string::String;
11	use alloc::vec::Vec;
12	use alloc::collections::BTreeMap;
13	
14	pub struct Loaded {
15	    pub entry: u64,
16	    pub code: Vec<(u64, Vec<u8>)>,     // (base address, bytes) of executable segments
17	    pub data: Vec<(u64, Vec<u8>)>,     // (base address, bytes) the code reads
18	    pub symbols: BTreeMap<String, u64>,
19	    pub format: &'static str,
20	    /// The machine the code is for, so a non-x86-64 binary is refused rather
21	    /// than silently misdecoded: "x86-64", "x86-32", "arm64", "arm", or a name.
22	    pub arch: &'static str,
23	}
24	
25	fn arch_name(machine: u64, kind: &str) -> &'static str {
26	    match kind {
27	        "elf" => match machine { 0x3E => "x86-64", 0x03 => "x86-32", 0xB7 => "arm64", 0x28 => "arm", 0xF3 => "riscv", _ => "other" },
28	        "pe"  => match machine { 0x8664 => "x86-64", 0x14c => "x86-32", 0xAA64 => "arm64", 0x1c0|0x1c4 => "arm", _ => "other" },
29	        "macho" => match machine { 0x0100_0007 => "x86-64", 0x0000_0007 => "x86-32", 0x0100_000C => "arm64", 0x0000_000C => "arm", _ => "other" },
30	        _ => "unknown",
31	    }
32	}
33	
34	fn le(raw: &[u8], o: usize, n: usize) -> u64 {
35	    let mut v = 0u64;
36	    for k in 0..n { if o + k < raw.len() { v |= (raw[o + k] as u64) << (8 * k); } }
37	    v
38	}
39	fn be(raw: &[u8], o: usize, n: usize) -> u64 {
40	    let mut v = 0u64;
41	    for k in 0..n { if o + k < raw.len() { v = (v << 8) | raw[o + k] as u64; } }
42	    v
43	}
44	
45	pub fn load(raw: &[u8]) -> Loaded {
46	    if raw.len() >= 4 {
47	        if &raw[0..4] == b"\x7fELF" { return elf(raw); }
48	        if &raw[0..2] == b"MZ"      { return pe(raw); }
49	        let m = le(raw, 0, 4);
50	        if m == 0xFEED_FACF || m == 0xFEED_FACE { return macho(raw, 0); }
51	        if be(raw, 0, 4) == 0xCAFE_BABE         { return macho_fat(raw); }
52	    }
53	    // raw / flat binary: the whole file as code, a conventional load base.
54	    Loaded { entry: 0x1000, code: alloc::vec![(0x1000, raw.to_vec())], data: Vec::new(),
55	             symbols: BTreeMap::new(), format: "raw", arch: "x86-64" }
56	}
57	
58	// ── ELF (32- and 64-bit) ──────────────────────────────────────────────────────
59	fn elf(raw: &[u8]) -> Loaded {
60	    let is64 = raw.get(4).copied() == Some(2);
61	    let mut out = Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), format: "elf", arch: arch_name(le(raw,18,2), "elf") };
62	    // header field widths and offsets differ by class
63	    let w = if is64 { 8usize } else { 4 };                 // address width
64	    out.entry = le(raw, 24, w);
65	    let shoff = le(raw, if is64 {0x28} else {0x20}, w) as usize;
66	    let shentsize = le(raw, if is64 {0x3a} else {0x2e}, 2) as usize;
67	    let shnum = le(raw, if is64 {0x3c} else {0x30}, 2) as usize;
68	    // section field offsets: sh_type, sh_flags, sh_addr, sh_offset, sh_size, sh_link, sh_entsize
69	    let (f_flags, f_addr, f_off, f_size, f_link, f_ent) = if is64 {
70	        (8, 16, 24, 32, 40, 56) } else { (8, 12, 16, 20, 24, 36) };
71	    let sh = |k: usize, f: usize, n: usize| le(raw, shoff + k * shentsize + f, n);
72	    for k in 0..shnum {
73	        let sh_type = sh(k, 4, 4);
74	        let sh_flags = sh(k, f_flags, w);
75	        let sh_addr = sh(k, f_addr, w);
76	        let sh_off = sh(k, f_off, w) as usize;
77	        let sh_size = sh(k, f_size, w) as usize;
78	        if sh_type == 1 && sh_off + sh_size <= raw.len() && sh_size > 0 && (sh_flags & 0x2) != 0 {
79	            let bytes = raw[sh_off..sh_off + sh_size].to_vec();
80	            if (sh_flags & 0x4) != 0 { out.code.push((sh_addr, bytes)); }
81	            else { out.data.push((sh_addr, bytes)); }
82	        }
83	    }
84	    // function symbols. Elf32_Sym is 16 bytes (name,value,size,info,other,shndx);
85	    // Elf64_Sym is 24 (name,info,other,shndx,value,size). info and value move.
86	    for k in 0..shnum {
87	        let sh_type = sh(k, 4, 4);
88	        if sh_type != 2 && sh_type != 11 { continue; }
89	        let sym_off = sh(k, f_off, w) as usize; let sym_size = sh(k, f_size, w) as usize;
90	        let strtab = sh(k, f_link, 4) as usize; let str_off = sh(strtab, f_off, w) as usize;
91	        let entsize: usize = if is64 { 24 } else { 16 };
92	        let ent = (sh(k, f_ent, w) as usize).max(entsize);
93	        let mut o = sym_off;
94	        while o + entsize <= sym_off + sym_size && o + entsize <= raw.len() {
95	            let st_name = le(raw, o, 4) as usize;
96	            let (st_info, st_value) = if is64 {
97	                (raw.get(o + 4).copied().unwrap_or(0), le(raw, o + 8, 8))
98	            } else {
99	                (raw.get(o + 12).copied().unwrap_or(0), le(raw, o + 4, 4))
100	            };
101	            if (st_info & 0xf) == 2 && st_value != 0 {
102	                let name = cstr(raw, str_off + st_name);
103	                if !name.is_empty() { out.symbols.insert(name, st_value); }
104	            }
105	            o += ent;
106	        }
107	    }
108	    out
109	}
110	
111	// ── PE ───────────────────────────────────────────────────────────────────────
112	fn pe(raw: &[u8]) -> Loaded {
113	    let mut out = Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), format: "pe", arch: "other" };
114	    let lfanew = le(raw, 0x3c, 4) as usize;
115	    if lfanew + 24 > raw.len() || &raw[lfanew..lfanew + 4] != b"PE\0\0" { return out; }
116	    let coff = lfanew + 4;
117	    out.arch = arch_name(le(raw, coff, 2), "pe");
118	    let nsec = le(raw, coff + 2, 2) as usize;
119	    let opt_size = le(raw, coff + 16, 2) as usize;
120	    let opt = coff + 20;
121	    let magic = le(raw, opt, 2);
122	    let (image_base, entry_rva) = if magic == 0x20b {
123	        (le(raw, opt + 24, 8), le(raw, opt + 16, 4))         // PE32+
124	    } else {
125	        (le(raw, opt + 28, 4), le(raw, opt + 16, 4))         // PE32
126	    };
127	    out.entry = image_base + entry_rva;
128	    let sects = opt + opt_size;
129	    for k in 0..nsec {
130	        let s = sects + k * 40;
131	        if s + 40 > raw.len() { break; }
132	        let vaddr = le(raw, s + 12, 4);
133	        let raw_size = le(raw, s + 16, 4) as usize;
134	        let raw_ptr = le(raw, s + 20, 4) as usize;
135	        let chars = le(raw, s + 36, 4);
136	        if raw_size == 0 || raw_ptr + raw_size > raw.len() { continue; }
137	        let bytes = raw[raw_ptr..raw_ptr + raw_size].to_vec();
138	        let base = image_base + vaddr;
139	        // IMAGE_SCN_MEM_EXECUTE 0x20000000, IMAGE_SCN_CNT_CODE 0x20
140	        if (chars & 0x2000_0000) != 0 || (chars & 0x20) != 0 { out.code.push((base, bytes)); }
141	        else if (chars & 0x4000_0000) != 0 { out.data.push((base, bytes)); }   // MEM_READ
142	    }
143	    out
144	}
145	
146	// ── Mach-O ───────────────────────────────────────────────────────────────────
147	fn macho_fat(raw: &[u8]) -> Loaded {
148	    let nfat = be(raw, 4, 4) as usize;
149	    for k in 0..nfat {
150	        let o = 8 + k * 20;
151	        let cputype = be(raw, o, 4);
152	        let offset = be(raw, o + 8, 4) as usize;
153	        if cputype == 0x0100_0007 && offset < raw.len() { return macho(raw, offset); }   // x86_64
154	    }
155	    if nfat > 0 { return macho(raw, be(raw, 16, 4) as usize); }
156	    Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), format: "macho-fat", arch: "other" }
157	}
158	
159	fn macho(raw: &[u8], base_off: usize) -> Loaded {
160	    let mut out = Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), format: "macho", arch: arch_name(le(raw, base_off+4, 4), "macho") };

