1	//! A machine that runs an IMASM module. Dispatch is on the glyph and nothing
2	//! else; what an instruction *was* in x86 survives only as payload the glyph
3	//! reads. Ported from imasm_vm.py. ⊞ engages the ALU, ⋈ links slots, ⊡ commits
4	//! to memory, ⊤ makes a truth and ⊥ consumes one, ∈ splits and ∋ fuses, > calls
5	//! and ⊣ terminates, < transfers, ⊙ transfers through data.
6	
7	use alloc::string::{String, ToString};
8	use alloc::vec::Vec;
9	use alloc::collections::BTreeMap;
10	use alloc::format;
11	
12	fn mask(size: u8) -> u128 {
13	    match size { 1 => 0xFF, 2 => 0xFFFF, 4 => 0xFFFF_FFFF, 8 => u64::MAX as u128, 16 => u128::MAX, _ => u64::MAX as u128 }
14	}
15	fn sign(v: u128, size: u8) -> i128 {
16	    let m = mask(size); let v = v & m;
17	    if v > m >> 1 { v as i128 - (m as i128 + 1) } else { v as i128 }
18	}
19	
20	/// (base register name, size in bytes, byte offset within base)
21	fn reg_info(name: &str) -> (&'static str, u8, u8) {
22	    const R64: [&str;16]=["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15"];
23	    // 64-bit
24	    for &r in R64.iter() { if name == r { return (r, 8, 0); } }
25	    // xmm
26	    if let Some(rest) = name.strip_prefix("xmm") { if rest.parse::<u8>().is_ok() {
27	        // return the canonical static string
28	        const X: [&str;16]=["xmm0","xmm1","xmm2","xmm3","xmm4","xmm5","xmm6","xmm7","xmm8","xmm9","xmm10","xmm11","xmm12","xmm13","xmm14","xmm15"];
29	        return (X[rest.parse::<usize>().unwrap()], 16, 0);
30	    }}
31	    if name == "rip" { return ("rip", 8, 0); }
32	    // e** (32-bit) and r**d
33	    let map32: [(&str,&str);16]=[("eax","rax"),("ecx","rcx"),("edx","rdx"),("ebx","rbx"),("esp","rsp"),("ebp","rbp"),("esi","rsi"),("edi","rdi"),
34	        ("r8d","r8"),("r9d","r9"),("r10d","r10"),("r11d","r11"),("r12d","r12"),("r13d","r13"),("r14d","r14"),("r15d","r15")];
35	    for (n,b) in map32 { if name==n { return (b,4,0); } }
36	    let map16: [(&str,&str);16]=[("ax","rax"),("cx","rcx"),("dx","rdx"),("bx","rbx"),("sp","rsp"),("bp","rbp"),("si","rsi"),("di","rdi"),
37	        ("r8w","r8"),("r9w","r9"),("r10w","r10"),("r11w","r11"),("r12w","r12"),("r13w","r13"),("r14w","r14"),("r15w","r15")];
38	    for (n,b) in map16 { if name==n { return (b,2,0); } }
39	    // 8-bit low
40	    let map8: [(&str,&str);16]=[("al","rax"),("cl","rcx"),("dl","rdx"),("bl","rbx"),("spl","rsp"),("bpl","rbp"),("sil","rsi"),("dil","rdi"),
41	        ("r8b","r8"),("r9b","r9"),("r10b","r10"),("r11b","r11"),("r12b","r12"),("r13b","r13"),("r14b","r14"),("r15b","r15")];
42	    for (n,b) in map8 { if name==n { return (b,1,0); } }
43	    // 8-bit high
44	    for (n,b) in [("ah","rax"),("ch","rcx"),("dh","rdx"),("bh","rbx")] { if name==n { return (b,1,1); } }
45	    ("rax", 8, 0)
46	}
