50	pub struct Machine {
51	    code: BTreeMap<u64, Vec<(char, Vec<String>)>>,
52	    addrs: Vec<u64>,
53	    next_of: BTreeMap<u64, u64>,
54	    pub entry: u64,
55	    reg: BTreeMap<String, u128>,
56	    mem: BTreeMap<u64, u8>,
57	    flags: (u128, u128, u8),
58	    kind: String,
59	    pub steps: u64,
60	    pub bits: u8,
61	    /// Parsed from the module's own `; sym NAME 0xADDR` lines, so a saved
62	    /// `.imasm` file resolves a symbol name without a second read of the
63	    /// original binary.
64	    pub symbols: BTreeMap<String, u64>,
65	}
