67	impl Machine {
68	    pub fn new(module: &str) -> Machine {
69	        let mut m = Machine {
70	            code: BTreeMap::new(), addrs: Vec::new(), next_of: BTreeMap::new(), entry: 0,
71	            reg: BTreeMap::new(), mem: BTreeMap::new(), flags: (0,0,1), kind: "cmp".into(), steps: 0, bits: 64,
72	            symbols: BTreeMap::new(),
73	        };
74	        for r in ["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15","rip"] {
75	            m.reg.insert(r.into(), 0);
76	        }
77	        for k in 0..16 { m.reg.insert(format!("xmm{}", k), 0); }
78	        m.reg.insert("rsp".into(), 0x7FFF_0000);
79	        m.parse(module);
80	        m
81	    }
