83	    fn parse(&mut self, text: &str) {
84	        let mut addr: Option<u64> = None;
85	        for line in text.lines() {
86	            if let Some(rest) = line.strip_prefix(';') {
87	                let t = rest.trim();
88	                if let Some(e) = t.strip_prefix("entry ") {
89	                    if let Ok(v) = u64::from_str_radix(e.trim().trim_start_matches("0x"), 16) { self.entry = v; }
90	                } else if let Some(b) = t.strip_prefix("bits ") {
91	                    if let Ok(v) = b.trim().parse::<u8>() { self.bits = v; }
92	                } else if let Some(s) = t.strip_prefix("sym ") {
93	                    let mut it = s.rsplitn(2, ' ');
94	                    if let (Some(addr_s), Some(name)) = (it.next(), it.next()) {
95	                        if let Ok(v) = u64::from_str_radix(addr_s.trim().trim_start_matches("0x"), 16) {
96	                            self.symbols.insert(name.to_string(), v);
97	                        }
98	                    }
99	                }
100	            } else if let Some(rest) = line.strip_prefix('=') {
101	                let mut it = rest.splitn(2, '\t');
102	                if let (Some(at), Some(blob)) = (it.next(), it.next()) {
103	                    if let Ok(a) = u64::from_str_radix(at.trim().trim_start_matches("0x"), 16) {
104	                        let bytes = hexbytes(blob);
105	                        for (k, b) in bytes.iter().enumerate() { if *b != 0 { self.mem.insert(a + k as u64, *b); } }
106	                    }
107	                }
108	            } else if let Some(rest) = line.strip_prefix('@') {
109	                if let Ok(a) = u64::from_str_radix(rest.trim().trim_start_matches("0x"), 16) {
110	                    addr = Some(a); self.code.entry(a).or_default();
111	                }
112	            } else if !line.is_empty() {
113	                if let Some(a) = addr {
114	                    let mut parts = line.split('\t');
115	                    if let Some(g) = parts.next() {
116	                        let glyph = g.chars().next().unwrap_or('?');
117	                        let fields: Vec<String> = parts.map(|s| s.to_string()).collect();
118	                        self.code.get_mut(&a).unwrap().push((glyph, fields));
119	                    }
120	                }
121	            }
122	        }
123	        self.addrs = self.code.keys().copied().collect();
124	        for w in self.addrs.windows(2) { self.next_of.insert(w[0], w[1]); }
125	    }
126	
127	    // ── slots ──
128	    fn get_reg(&self, name: &str) -> u128 {
129	        let (base, size, off) = reg_info(name);
130	        (self.reg[base] >> (off as u32 * 8)) & mask(size)
131	    }
132	    fn set_reg(&mut self, name: &str, val: u128) {
133	        let (base, size, off) = reg_info(name);
134	        let cur = self.reg.get(base).copied().unwrap_or(0);
135	        let nv = match size {
136	            8 => val & mask(8),
137	            4 => val & mask(4),           // 32-bit writes zero the top
138	            16 => val & mask(16),
139	            _ => { let m = mask(size) << (off as u32 * 8); (cur & !m) | ((val << (off as u32 * 8)) & m) }
140	        };
141	        self.reg.insert(base.to_string(), nv);
142	    }
143	    fn load(&self, addr: u64, size: u8) -> u128 {
144	        let mut v = 0u128;
145	        for k in 0..size as u64 { v |= (*self.mem.get(&(addr + k)).unwrap_or(&0) as u128) << (8 * k); }
146	        v
147	    }
148	    fn store(&mut self, addr: u64, val: u128, size: u8) {
149	        let v = val & mask(size);
150	        for k in 0..size as u64 { self.mem.insert(addr + k, ((v >> (8*k)) & 0xFF) as u8); }
151	    }
152	    fn ea(&self, field: &str) -> (u64, u8) {
153	        // m:base:index:scale:disp:size
154	        let parts: Vec<&str> = field.split(':').collect();
155	        let base = parts[1]; let index = parts[2]; let scale = parts[3];
156	        let disp = parts[4]; let size: u8 = parts[5].parse().unwrap_or(8);
157	        let mut a: i128 = if !base.is_empty() { self.get_reg(base) as i128 } else { 0 };
158	        if !index.is_empty() { a += self.get_reg(index) as i128 * scale.parse::<i128>().unwrap_or(1); }
159	        a += parse_imm(disp);
160	        ((a as u128 & mask(8)) as u64, size)
161	    }
162	    fn read(&self, field: &str, size_hint: u8) -> (u128, u8) {
163	        match field.as_bytes()[0] {
164	            b'r' => { let n = &field[2..]; (self.get_reg(n), reg_info(n).1) }
165	            b'i' => ((parse_imm(&field[2..]) as u128) & mask(8), size_hint),
166	            _ => { let (a, s) = self.ea(field); (self.load(a, s), s) }
167	        }
168	    }
169	    fn write(&mut self, field: &str, val: u128) {
170	        if field.as_bytes()[0] == b'r' { self.set_reg(&field[2..], val); }
171	        else { let (a, s) = self.ea(field); self.store(a, val, s); }
172	    }
173	    fn width(&self, field: &str) -> u8 {
174	        match field.as_bytes()[0] {
175	            b'r' => reg_info(&field[2..]).1,
176	            b'm' => field.rsplit(':').next().and_then(|s| s.parse().ok()).unwrap_or(8),
177	            _ => 8,
178	        }
179	    }
180	
181	    // ── truth ──
182	    fn cc(&self, name: &str) -> bool {
183	        let (a, b, size) = self.flags;
184	        let (zf, sf, cf, of);
185	        if self.kind == "test" {
186	            let r = (a & b) & mask(size);
187	            zf = r == 0; sf = sign(r, size) < 0; cf = false; of = false;
188	        } else {
189	            let r = a.wrapping_sub(b) & mask(size);
190	            zf = r == 0; sf = sign(r, size) < 0;
191	            cf = (a & mask(size)) < (b & mask(size));
192	            of = (sign(a, size) - sign(b, size)) != sign(r, size);
193	        }
194	        match name {
195	            "e"|"z" => zf, "ne"|"nz" => !zf,
196	            "s" => sf, "ns" => !sf,
197	            "b"|"nae"|"c" => cf, "ae"|"nb"|"nc" => !cf,
198	            "be"|"na" => cf||zf, "a"|"nbe" => !(cf||zf),
199	            "l"|"nge" => sf!=of, "ge"|"nl" => sf==of,
200	            "le"|"ng" => zf||(sf!=of), "g"|"nle" => !zf&&sf==of,
201	            "o" => of, "no" => !of, "p" => false, "np" => true,
202	            _ => false,
203	        }
204	    }
205	    fn set_flags(&mut self, a: u128, b: u128, size: u8, kind: &str) { self.flags = (a, b, size); self.kind = kind.to_string(); }
206	
207	    fn slot(&self) -> u8 { self.bits / 8 }              // stack slot width, 8 or 4
208	    fn push_val(&mut self, v: u128) { let s = self.slot(); self.set_reg("rsp", self.get_reg("rsp").wrapping_sub(s as u128)); let sp = self.get_reg("rsp") as u64; self.store(sp, v, s); }
209	    fn pop_val(&mut self) -> u128 { let s = self.slot(); let sp = self.get_reg("rsp") as u64; let v = self.load(sp, s); self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); v }
210	
211	    fn do_syscall(&mut self) -> Result<(), Stop> {
212	        let num = sign(self.get_reg("rax"), 8);
213	        let a0 = self.get_reg("rdi"); let _a1 = self.get_reg("rsi"); let _a2 = self.get_reg("rdx");
214	        if num == 60 || num == 231 { return Err(Stop::SysExit((sign(a0,8) & 0xFF) as i32)); }
215	        // write and others: this is a function tester; anything but exit returns -ENOSYS
216	        self.set_reg("rax", (-38i128 as u128) & mask(8));
217	        Ok(())
218	    }
