220	    // ── ALU ──
221	    fn alu(&mut self, op: &str, f: &[String]) {
222	        match op {
223	            "nop"|"endbr64"|"endbr32" => return,
224	            "lea" => { let (a,_) = self.ea(&f[1]); self.write(&f[0], a as u128); return; }
225	            "cdq"|"cltd" => { let v = if sign(self.get_reg("eax"),4) < 0 { mask(4) } else { 0 }; self.set_reg("edx", v); return; }
226	            "cqo" => { let v = if sign(self.get_reg("rax"),8) < 0 { mask(8) } else { 0 }; self.set_reg("rdx", v); return; }
227	            "cdqe"|"cltq" => { let v = (sign(self.get_reg("eax"),4) as u128) & mask(8); self.set_reg("rax", v); return; }
228	            "idiv"|"div" => {
229	                let size = self.width(&f[0]);
230	                let d = self.read(&f[0], size).0;
231	                let (lo_n, hi_n) = ([8u8,4,2,1].contains(&size), true); let _ = (lo_n, hi_n);
232	                let lo = self.get_reg(match size {8=>"rax",4=>"eax",2=>"ax",_=>"al"});
233	                let hi = self.get_reg(match size {8=>"rdx",4=>"edx",2=>"dx",_=>"ah"});
234	                let (q, r);
235	                if op == "idiv" {
236	                    let n = sign((hi << (size as u32 *8)) | lo, if size < 8 { size*2 } else { 8 });
237	                    let dd = sign(d, size);
238	                    let qq = (n.abs() / dd.abs()) * if (n<0)==(dd<0) {1} else {-1};
239	                    q = (qq as u128) & mask(size); r = ((n - qq*dd) as u128) & mask(size);
240	                } else {
241	                    let n = (hi << (size as u32 *8)) | lo;
242	                    q = (n / d) & mask(size); r = (n % d) & mask(size);
243	                }
244	                self.set_reg(match size {8=>"rax",4=>"eax",2=>"ax",_=>"al"}, q);
245	                self.set_reg(match size {8=>"rdx",4=>"edx",2=>"dx",_=>"ah"}, r);
246	                return;
247	            }
248	            _ => {}
249	        }
250	        if is_simd(op) { self.simd(op, f); return; }
251	
252	        let size = self.width(&f[0]);
253	        let a = self.read(&f[0], size).0;
254	        if matches!(op, "not"|"neg"|"inc"|"dec") {
255	            let r = match op { "not" => !a, "neg" => (a as i128).wrapping_neg() as u128, "inc" => a.wrapping_add(1), _ => a.wrapping_sub(1) };
256	            self.write(&f[0], r & mask(size));
257	            if op != "not" { self.set_flags(r & mask(size), 0, size, "cmp"); }
258	            return;
259	        }
260	        // One-operand imul/mul: the full 2*size product lands in edx:eax
261	        // (rdx:rax at 64-bit). Dropping the high half silently breaks every
262	        // magic-number division the compiler emits.
263	        if (op == "imul" || op == "mul") && f.len() == 1 {
264	            let (lo_r, hi_r) = match size { 8 => ("rax","rdx"), 4 => ("eax","edx"), 2 => ("ax","dx"), _ => ("al","ah") };
265	            let prod: u128 = if op == "imul" {
266	                ((sign(self.get_reg(lo_r), size)).wrapping_mul(sign(a, size))) as u128
267	            } else {
268	                (self.get_reg(lo_r) & mask(size)).wrapping_mul(a & mask(size))
269	            };
270	            self.set_reg(lo_r, prod & mask(size));
271	            let hi = (prod >> (size as u32 * 8)) & mask(size);
272	            self.set_reg(hi_r, hi);
273	            self.set_flags(prod & mask(size), 0, size, "cmp");
274	            return;
275	        }
276	        if op == "imul" && f.len() == 3 {
277	            let x = self.read(&f[1], size).0; let y = self.read(&f[2], size).0;
278	            let r = (sign(x, size) * sign(y, size)) as u128;
279	            self.write(&f[0], r & mask(size));
280	            self.set_flags(r & mask(size), 0, size, "cmp");
281	            return;
282	        }
283	        let b = self.read(&f[f.len()-1], size).0;
284	        let r: u128 = match op {
285	            "add"|"adc" => a.wrapping_add(b),
286	            "sub"|"sbb" => a.wrapping_sub(b),
287	            "and" => a & b, "or" => a | b, "xor" => a ^ b,
288	            "imul" => (sign(a,size) * sign(b,size)) as u128,
289	            "shl"|"sal" => a.wrapping_shl((b & 63) as u32),
290	            "shr" => (a & mask(size)) >> (b & 63),
291	            "sar" => (sign(a,size) >> (b & 63)) as u128,
292	            _ => a,
293	        };
294	        self.write(&f[0], r & mask(size));
295	        self.set_flags(r & mask(size), 0, size, "cmp");
296	    }
