298	    fn simd(&mut self, op: &str, f: &[String]) {
299	        let dst = f[0].clone();
300	        match op {
301	            "movdqa"|"movdqu"|"movaps"|"movups" => { let v = self.read(&f[1], 16).0; self.write(&dst, v & mask(16)); }
302	            "movd"|"movq" => {
303	                let w = if op == "movd" { 4 } else { 8 };
304	                let src_is_x = f[1].starts_with("r:xmm");
305	                let v = self.read(&f[1], w).0;
306	                if dst.starts_with("r:xmm") { self.write(&dst, v & mask(w)); }
307	                else { self.write(&dst, if src_is_x { v & mask(w) } else { v }); }
308	            }
309	            "psrldq" => { let a = self.read(&dst,16).0; let n = parse_imm(&f[1][2..]) as u32; self.write(&dst, (a >> (n*8)) & mask(16)); }
310	            "psrlq"|"psllq" => {
311	                let a = self.read(&dst,16).0;
312	                let n = if f[1].as_bytes()[0]==b'i' { parse_imm(&f[1][2..]) as u32 } else { self.read(&f[1],8).0 as u32 };
313	                let lanes = [ (a & mask(8)), (a >> 64) & mask(8) ];
314	                let r: [u128;2] = if op=="psrlq" { [lanes[0]>>n, lanes[1]>>n] } else { [(lanes[0]<<n)&mask(8), (lanes[1]<<n)&mask(8)] };
315	                self.write(&dst, r[0] | (r[1] << 64));
316	            }
317	            "pshufd" => {
318	                let a = self.read(&f[1],16).0; let sel = parse_imm(&f[2][2..]) as u128;
319	                let l = [a&mask(4),(a>>32)&mask(4),(a>>64)&mask(4),(a>>96)&mask(4)];
320	                let mut o=0u128; for k in 0..4 { let s=((sel>>(2*k))&3) as usize; o |= l[s] << (32*k); }
321	                self.write(&dst, o);
322	            }
323	            "punpcklqdq" => { let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0; self.write(&dst, (a&mask(8))|((b&mask(8))<<64)); }
324	            "punpckldq" => {
325	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
326	                let x=[a&mask(4),(a>>32)&mask(4)]; let y=[b&mask(4),(b>>32)&mask(4)];
327	                self.write(&dst, x[0] | (y[0]<<32) | (x[1]<<64) | (y[1]<<96));
328	            }
329	            "pmuludq" => {
330	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
331	                let x0=a&mask(4); let x2=(a>>64)&mask(4); let y0=b&mask(4); let y2=(b>>64)&mask(4);
332	                self.write(&dst, (x0*y0) | ((x2*y2)<<64));
333	            }
334	            "pxor"|"pand"|"por" => { let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
335	                self.write(&dst, match op {"pxor"=>a^b,"pand"=>a&b,_=>a|b}); }
336	            _ => { // lane-wise padd/psub/pmull
337	                let a=self.read(&dst,16).0; let b=self.read(&f[1],16).0;
338	                let w: u8 = match op.chars().last().unwrap() {'b'=>1,'w'=>2,'d'=>4,'q'=>8,_=>4};
339	                let n = 16 / w; let mut o=0u128;
340	                for k in 0..n {
341	                    let sh = (k*w) as u32 * 8;
342	                    let p = (a >> sh) & mask(w); let q = (b >> sh) & mask(w);
343	                    let v = if op.starts_with("padd") { p.wrapping_add(q) } else if op.starts_with("psub") { p.wrapping_sub(q) } else { p.wrapping_mul(q) };
344	                    o |= (v & mask(w)) << sh;
345	                }
346	                self.write(&dst, o);
347	            }
348	        }
349	    }
