351	    fn step(&mut self, addr: u64) -> Result<Option<u64>, Stop> {
352	        let next = self.next_of.get(&addr).copied().unwrap_or(0);
353	        self.reg.insert("rip".into(), next as u128);
354	        let insns = self.code.get(&addr).cloned().unwrap_or_default();
355	        for (glyph, f) in insns {
356	            match glyph {
357	                '∋' => continue,
358	                '⊣' => {
359	                    if f.get(0).map(|s| s.as_str()) == Some("leave") {
360	                        let s = self.slot();
361	                        let rbp = self.get_reg("rbp"); self.set_reg("rsp", rbp);
362	                        let v = self.load(self.get_reg("rsp") as u64, s); self.set_reg("rbp", v);
363	                        self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); continue;
364	                    }
365	                    let ret = self.pop_val();
366	                    // ret imm16: stdcall callee-cleanup of stack args.
367	                    if let Some(im) = f.get(1) { if im.as_bytes().get(0) == Some(&b'i') {
368	                        let n = parse_imm(&im[2..]) as u128;
369	                        self.set_reg("rsp", self.get_reg("rsp").wrapping_add(n));
370	                    }}
371	                    return Ok(Some(ret as u64));
372	                }
373	                '⊤' => { let size=self.width(&f[1]); let a=self.read(&f[1],size).0; let b=self.read(&f[2],size).0; self.set_flags(a,b,size,&f[0]); }
374	                '∈' => { if self.cc(&f[0]) { return Ok(Some(parse_imm(&f[1][2..]) as u64)); } }
375	                '≺' => { return Ok(Some(parse_imm(&f[1][2..]) as u64)); }
376	                '⊙' => {
377	                    if f.get(0).map(|s|s.as_str()) == Some("syscall") { self.do_syscall()?; continue; }
378	                    if f.get(0).map(|s|s.as_str()) == Some("external") { return Err(Stop::Halt(format!("external {}", f.get(1).cloned().unwrap_or_default()))); }
379	                    let tgt = self.read(&f[1], 8).0;
380	                    if f.get(0).map(|s|s.as_str()) == Some("call") { self.push_val(next as u128); }
381	                    return Ok(Some(tgt as u64));
382	                }
383	                '≻' => {
384	                    self.push_val(next as u128);
385	                    return Ok(Some(parse_imm(&f[1][2..]) as u64));
386	                }
387	                '⋈' | '⊡' => {
388	                    let op = f[0].as_str();
389	                    match op {
390	                        "push" => { let v=self.read(&f[1],self.slot()).0; self.push_val(v); }
391	                        "pop" => { let v=self.pop_val(); self.write(&f[1], v); }
392	                        "leave" => { let s=self.slot(); let rbp=self.get_reg("rbp"); self.set_reg("rsp",rbp); let v=self.load(self.get_reg("rsp") as u64,s); self.set_reg("rbp",v); self.set_reg("rsp", self.get_reg("rsp").wrapping_add(s as u128)); }
393	                        "xchg" => { let x=self.read(&f[1],8).0; let y=self.read(&f[2],8).0; self.write(&f[1],y); self.write(&f[2],x); }
394	                        "mov"|"movabs" => { let w=self.width(&f[1]); let v=self.read(&f[2],w).0; self.write(&f[1], v & mask(w)); }
395	                        "movzx" => { let v=self.read(&f[2],8).0; self.write(&f[1], v & mask(self.width(&f[2]))); }
396	                        "movsx"|"movsxd" => { let sw=self.width(&f[2]); let v=self.read(&f[2],8).0; self.write(&f[1], (sign(v,sw) as u128) & mask(self.width(&f[1]))); }
397	                        _ => self.alu(op, &f[1..]),
398	                    }
399	                }
400	                '⊥' => {
401	                    if f.get(1).map(|s|s.as_str()) == Some("set") { let v = if self.cc(&f[0]) {1} else {0}; self.write(&f[2], v); }
402	                    else if self.cc(&f[0]) { let w=self.width(&f[2]); let v=self.read(&f[3],w).0; self.write(&f[2], v); }
403	                }
404	                '⊞' => self.alu(&f[0], &f[1..]),
405	                _ => {}
406	            }
407	        }
408	        Ok(self.next_of.get(&addr).copied())
409	    }
410	
411	    /// Resolve a symbol name to its address from the module's own embedded
412	    /// table (`; sym NAME 0xADDR`) — no second read of the original binary.
413	    pub fn resolve(&self, name: &str) -> Option<u64> { self.symbols.get(name).copied() }
414	
415	    /// Run one function to its ⊣. 64-bit takes integer args in registers (System
416	    /// V); 32-bit takes them on the stack (cdecl). Returns eax.
417	    pub fn call(&mut self, addr: u64, args: &[i64], limit: u64) -> Result<i64, Stop> {
418	        let sentinel: u64 = 0xDEAD_0000;
419	        if self.bits == 32 {
420	            // cdecl: args pushed right-to-left, then the return address on top.
421	            for v in args.iter().rev() { self.push_val((*v as u32) as u128); }
422	            self.push_val(sentinel as u128);
423	        } else {
424	            for (name, v) in ["rdi","rsi","rdx","rcx","r8","r9"].iter().zip(args) {
425	                self.set_reg(name, (*v as u128) & mask(8));
426	            }
427	            self.push_val(sentinel as u128);
428	        }
429	        let mut pc = addr; self.steps = 0;
430	        let mut trace: Vec<String> = Vec::new();
431	        while pc != sentinel {
432	            if !self.code.contains_key(&pc) {
433	                return Err(Stop::Halt(format!("no instruction at 0x{:x} after {} steps\n  previous 12:\n{}", pc, self.steps, trace.join("\n"))));
434	            }
435	            if trace.len() >= 12 { trace.remove(0); }
436	            let insn_txt = self.code.get(&pc).map(|v| v.iter().map(|(g,f)| format!("{} {}", g, f.join(" "))).collect::<Vec<_>>().join(" ; ")).unwrap_or_default();
437	            trace.push(format!("  {:04x}: {}", pc, insn_txt));
438	            match self.step(pc)? {
439	                Some(n) => pc = n,
440	                None => return Err(Stop::Halt(format!("ran off the end after {} steps\n  previous 12:\n{}", self.steps, trace.join("\n")))),
441	            }
442	            self.steps += 1;
443	            if self.steps > limit { return Err(Stop::Halt(format!("ran off the end after {} steps", self.steps))); }
444	        }
445	        Ok(sign(self.get_reg("eax"), 4) as i64)
446	    }
447	}
448	
449	fn is_simd(op: &str) -> bool {
450	    matches!(op, "movdqa"|"movdqu"|"movaps"|"movups"|"movd"|"movq"|"pxor"|"pand"|"por"
451	        |"paddd"|"paddq"|"paddw"|"paddb"|"psubd"|"psubq"|"psubw"|"psubb"|"pmulld"|"pmuludq"
452	        |"psrlq"|"psllq"|"psrldq"|"pshufd"|"punpckldq"|"punpcklqdq")
453	}
454	
455	fn hexbytes(s: &str) -> Vec<u8> {
456	    let mut out = Vec::new(); let mut hi: Option<u8> = None;
457	    for ch in s.chars() {
458	        let v = match ch { '0'..='9'=>ch as u8-b'0','a'..='f'=>ch as u8-b'a'+10,'A'..='F'=>ch as u8-b'A'+10,_=>continue };
459	        match hi { None=>hi=Some(v), Some(h)=>{ out.push((h<<4)|v); hi=None; } }
460	    }
461	    out
462	}
463	
464	/// Parse an immediate spelled "0x1a" or "-0x1a".
465	fn parse_imm(s: &str) -> i128 {
466	    let s = s.trim();
467	    if let Some(rest) = s.strip_prefix('-') {
468	        -(i128::from_str_radix(rest.trim_start_matches("0x"), 16).unwrap_or(0))
469	    } else {
470	        i128::from_str_radix(s.trim_start_matches("0x"), 16).unwrap_or(0)
471	    }
472	}
