pub fn pairing(word: &[char]) -> (Vec<Region>, Vec<usize>, Vec<usize>) {
    let (pairs, un_split, un_fuse) = cyclic_pairs(word);
    let regions = pairs.into_iter().map(|(si, fj)| {
