fn compute_value_period(trace: &[B4; 16], head: usize) -> usize {
    // Look at the ring buffer as if head points to the next write slot.
    // The most recent value is at (head + 15) % 16.
    // Try periods from 1..=16.
    for p in 1..=16 {
