const exec = {
            playing: true,
            ip: 0,              // current station index (just arrived / firing)
            next: 1,           // next station (wraps)
            phase: 0,          // 0..1 progress along arc ip → next
            tick: 0,           // completed token firings
            winding: 0,        // full ring revolutions (IP wraps past end)
            speed: 1,          // stations per second (approx)
            dwell: 0.28,       // fraction of segment spent "firing" at station
            stack: [],         // B4 stack (kernel carrier: N/T/F/B)
            lastFired: -1,
            pulse: 0,
            transit: false,    // transit mode: slow down while a reroute (split/exotic pulse) is in flight
            history: []        // snapshots taken before each advance, for step-back (stack is lossy — undo by restore, not by inverting fireToken)
        };

        // B4 stack effects mirroring mOMonadOS kernel token semantics.
        function fireToken(i) {
            const t = TOKENS[i];
            const push = v => { exec.stack.push(v); if (exec.stack.length > 8) exec.stack.shift(); };
            const pop = () => (exec.stack.length ? exec.stack.pop() : 'N');
            switch (t.name) {
                case 'VINIT':  push('N'); break;
                case 'IMSCRIB': /* self-read into regs — no stack change */ break;
                case 'FSPLIT':  push(exec.stack.length ? exec.stack[exec.stack.length - 1] : 'N'); break;
                case 'EVALT': {
                    const v = pop();
                    push(v === 'T' ? 'T' : (v === 'B' ? 'N' : 'N'));
                    break;
                }
                case 'EVALF': {
                    const v = pop();
                    push(v === 'F' ? 'F' : (v === 'B' ? 'N' : 'N'));
                    break;
                }
                case 'FFUSE': {
                    const a = pop(), b = pop();
                    // join: N|x=x, T|F=B, etc. simplified
                    if (a === 'B' || b === 'B' || (a === 'T' && b === 'F') || (a === 'F' && b === 'T')) push('B');
                    else if (a === 'N') push(b);
                    else if (b === 'N') push(a);
                    else push(a);
                    break;
                }
