1	// rebis/translate.rs — Gene→Protein Translation Pipeline
2	//
3	// Port of rhr_p4rky/gene_to_protein_pipeline.py.
4	// Full bidirectional gene↔protein translation with Frobenius verification
5	// at every step: DNA↔mRNA→codon↔amino acid↔protein chain.
6	//
7	// Added reverse direction: Protein → mRNA (all degenerate codons enumerated).
8	
9	use crate::rebis::codon::{Codon, CodeTable, translate_codon, translate_codon_table, b4_to_nucleotide};
10	use crate::rebis::AminoAcid;
11	use alloc::string::String;
12	use alloc::vec::Vec;
13	
14	/// Transcription: DNA coding strand → mRNA (T→U only, NO complement).
15	/// DNA: ATGGCC → mRNA: AUGGCC. The coding strand IS the mRNA with T→U.
16	pub fn transcribe(dna: &[u8]) -> Vec<u8> {
17	    dna.iter().map(|&b| {
18	        match b {
19	            b'T' | b't' => b'U',
20	            other => other.to_ascii_uppercase(),
21	        }
22	    }).collect()
23	}
24	
25	/// Reverse transcription: mRNA → DNA (U→T, no complement).
26	/// mRNA: AUGGCC → DNA: ATGGCC. Just U→T.
27	pub fn reverse_transcribe(mrna: &[u8]) -> Vec<u8> {
28	    mrna.iter().map(|&b| {
29	        match b {
30	            b'U' | b'u' => b'T',
31	            other => other.to_ascii_uppercase(),
32	        }
33	    }).collect()
34	}
35	
36	/// Translation: mRNA → amino acid chain.
37	/// Finds the first AUG (start), translates codons, stops at stop codon.
38	pub fn translate(mrna: &[u8]) -> (Vec<AminoAcid>, usize) {
39	    let mut chain = Vec::new();
40	    let mut start_idx = None;
41	
42	    // Find start codon (AUG)
43	    for i in 0..mrna.len().saturating_sub(2) {
44	        if mrna[i] == b'A' && mrna[i+1] == b'U' && mrna[i+2] == b'G' {
45	            start_idx = Some(i);
46	            break;
47	        }
48	    }
49	
50	    let start = match start_idx {
51	        Some(i) => i,
52	        None => return (chain, 0),
53	    };
54	
55	    // Translate codons from start
56	    let mut pos = start;
57	    while pos + 2 < mrna.len() {
58	        let codon = match Codon::from_bytes(mrna[pos], mrna[pos+1], mrna[pos+2]) {
59	            Ok(c) => c,
60	            Err(_) => break,
61	        };
62	        let aa = translate_codon(&codon);
63	        if aa == AminoAcid::Stop {
64	            chain.push(aa); // record stop
65	            break;
66	        }
67	        chain.push(aa);
68	        pos += 3;
69	    }
70	
71	    (chain, pos + 3 - start)
72	}
73	
74	// ── Amino Acid Parsing ──────────────────────────────────────────
75	
76	/// Parse an amino acid from a 3-letter code, 1-letter code, or full name.
77	/// Case-insensitive. Returns None if unrecognized.
78	pub fn parse_aa(s: &str) -> Option<AminoAcid> {
79	    match s.to_uppercase().as_str() {
80	        // Three-letter codes
81	        "PHE" | "F" => Some(AminoAcid::Phe),
82	        "LEU" | "L" => Some(AminoAcid::Leu),
83	        "ILE" | "I" => Some(AminoAcid::Ile),
84	        "MET" | "M" => Some(AminoAcid::Met),
85	        "VAL" | "V" => Some(AminoAcid::Val),
86	        "SER" | "S" => Some(AminoAcid::Ser),
87	        "PRO" | "P" => Some(AminoAcid::Pro),
88	        "THR" | "T" => Some(AminoAcid::Thr),
89	        "ALA" | "A" => Some(AminoAcid::Ala),
90	        "TYR" | "Y" => Some(AminoAcid::Tyr),
91	        "STOP" | "STP" | "*" => Some(AminoAcid::Stop),
92	        "HIS" | "H" => Some(AminoAcid::His),
93	        "GLN" | "Q" => Some(AminoAcid::Gln),
94	        "ASN" | "N" => Some(AminoAcid::Asn),
95	        "LYS" | "K" => Some(AminoAcid::Lys),
96	        "ASP" | "D" => Some(AminoAcid::Asp),
97	        "GLU" | "E" => Some(AminoAcid::Glu),
98	        "CYS" | "C" => Some(AminoAcid::Cys),
99	        "TRP" | "W" => Some(AminoAcid::Trp),
100	        "ARG" | "R" => Some(AminoAcid::Arg),
101	        "GLY" | "G" => Some(AminoAcid::Gly),
102	        _ => None,
103	    }
104	}
105	
106	/// Get the 1-letter code for an amino acid.
107	pub fn aa_letter(aa: AminoAcid) -> &'static str {
108	    match aa {
109	        AminoAcid::Phe => "F", AminoAcid::Leu => "L", AminoAcid::Ile => "I",
110	        AminoAcid::Met => "M", AminoAcid::Val => "V", AminoAcid::Ser => "S",
111	        AminoAcid::Pro => "P", AminoAcid::Thr => "T", AminoAcid::Ala => "A",
112	        AminoAcid::Tyr => "Y", AminoAcid::Stop => "*", AminoAcid::His => "H",
113	        AminoAcid::Gln => "Q", AminoAcid::Asn => "N", AminoAcid::Lys => "K",
114	        AminoAcid::Asp => "D", AminoAcid::Glu => "E", AminoAcid::Cys => "C",
115	        AminoAcid::Trp => "W", AminoAcid::Arg => "R", AminoAcid::Gly => "G",
116	    }
117	}
118	
119	// ── Reverse Translation (Protein → RNA) ─────────────────────────
120	
121	/// The result of reverse-translating a single amino acid:
122	/// one or more codons that could encode it.
123	#[derive(Debug)]
124	pub struct ReverseHit {
125	    pub aa: AminoAcid,
126	    pub codons: Vec<Codon>,
127	    pub codon_count: usize,     // degeneracy
128	}
129	
130	/// Reverse translate an amino acid: return ALL codons that encode it.
131	pub fn reverse_translate_aa(aa: AminoAcid) -> ReverseHit {
132	    use crate::rebis::genetics::codons_for_aa;
133	    let codons = codons_for_aa(aa);
134	    ReverseHit {
135	        aa,
136	        codon_count: codons.len(),
137	        codons,
138	    }
139	}
140	
141	/// Format a codon as a 3-letter RNA string.
142	pub fn codon_to_rna(c: &Codon) -> [u8; 3] {
143	    [b4_to_nucleotide(c.p1), b4_to_nucleotide(c.p2), b4_to_nucleotide(c.p3)]
144	}
145	
146	/// Reverse translate a full protein chain to ALL possible mRNA sequences.
147	/// Returns a vector where each element is the set of possible codons for that position.
148	pub fn reverse_translate_chain(chain: &[AminoAcid]) -> Vec<ReverseHit> {
149	    chain.iter().map(|&aa| reverse_translate_aa(aa)).collect()
150	}
151	
152	/// Enumerate ALL possible mRNA sequences for a protein chain.
153	/// WARNING: Product of degeneracies. A chain of 4 AAs averaging 4 codons
154	/// each produces 4^4=256 sequences. Use with care.
155	/// Returns the total count and an iterator-like Vec of sequences.
156	pub fn enumerate_mrna(chain: &[AminoAcid]) -> Vec<Vec<u8>> {
157	    if chain.is_empty() {
158	        return Vec::new();
159	    }
160	
161	    use crate::rebis::genetics::codons_for_aa;
162	
163	    // Start with the first AA's codons
164	    let first = codons_for_aa(chain[0]);
165	    if first.is_empty() {
166	        return Vec::new();
167	    }
168	
169	    let mut sequences: Vec<Vec<u8>> = first.iter().map(|c| {
170	        Vec::from(codon_to_rna(c).as_slice())
171	    }).collect();
172	
173	    // For each subsequent AA, extend all sequences with its codons
174	    for &aa in &chain[1..] {
175	        let codons = codons_for_aa(aa);
176	        if codons.is_empty() {
177	            break;
178	        }
179	        let mut new_seqs = Vec::with_capacity(sequences.len() * codons.len());
180	        for seq in &sequences {
181	            for c in &codons {
182	                let mut ext = seq.clone();
183	                ext.extend_from_slice(&codon_to_rna(c));
184	                new_seqs.push(ext);
185	            }
186	        }
187	        sequences = new_seqs;
188	    }
189	
190	    sequences
191	}
192	
193	/// Reverse translation: amino acid chain → canonical codon sequence.
194	/// For each AA, returns the FIRST codon (sorted by index, which groups U→A→C→G).
195	/// This is the "canonical" representative.
196	pub fn reverse_translate(chain: &[AminoAcid]) -> Vec<u8> {
197	    use crate::rebis::genetics::codons_for_aa;
198	    let mut mrna = Vec::new();
199	    for &aa in chain {
200	        let codons = codons_for_aa(aa);
201	        if codons.is_empty() { break; }
202	        let c = &codons[0];
203	        mrna.push(b4_to_nucleotide(c.p1));
204	        mrna.push(b4_to_nucleotide(c.p2));
205	        mrna.push(b4_to_nucleotide(c.p3));
206	    }
207	    mrna
208	}
209	
210	// ── Pipeline ────────────────────────────────────────────────────
211	
212	/// Full gene → protein pipeline with verification.
213	#[derive(Debug)]
214	pub struct TranslationResult {
215	    pub mrna: Vec<u8>,
216	    pub protein: Vec<AminoAcid>,
217	    pub coding_length: usize,
218	    pub start_codon_pos: usize,
219	    pub stop_codon_present: bool,
220	    pub frobenius_verified: bool,
221	    pub primitive_labels: Vec<Option<&'static str>>,
222	    pub code_table: CodeTable,
223	}
224	
225	/// Run the full gene→protein pipeline on a DNA sequence.
226	pub fn run_pipeline(dna: &[u8]) -> TranslationResult {
227	    run_pipeline_table(dna, CodeTable::Standard)
228	}
229	
230	/// Run the pipeline with a specific genetic code table.
231	pub fn run_pipeline_table(dna: &[u8], code_table: CodeTable) -> TranslationResult {
232	    use crate::rebis::genetics::codons_for_aa_table;
233	
234	    let mrna = transcribe(dna);
235	    let start = mrna.windows(3).position(|w| w == b"AUG");
236	
237	    // Find start, translate codons
238	    let mut protein: Vec<AminoAcid> = Vec::new();
239	    let mut coding_len = 0usize;
240	    let mut pos = match start {
241	        Some(i) => i,
242	        None => {
243	            return TranslationResult {
244	                mrna, protein, coding_length: 0, start_codon_pos: 0,
245	                stop_codon_present: false, frobenius_verified: false,
246	                primitive_labels: Vec::new(), code_table,
247	            };
248	        }
249	    };
250	    let start_pos = pos;
251	    while pos + 2 < mrna.len() {
252	        let codon = match Codon::from_bytes(mrna[pos], mrna[pos+1], mrna[pos+2]) {
253	            Ok(c) => c, Err(_) => break,
254	        };
255	        let aa = translate_codon_table(&codon, code_table);
256	        protein.push(aa);
257	        if aa == AminoAcid::Stop { coding_len = pos + 3 - start_pos; break; }
258	        pos += 3;
259	    }
260	    if coding_len == 0 && !protein.is_empty() {
261	        coding_len = protein.len() * 3;
262	    }
263	    let stop_present = protein.last() == Some(&AminoAcid::Stop);
264	
265	    // Frobenius round-trip: Protein→canonical mRNA→Protein using same table
266	    let non_stop: Vec<AminoAcid> = protein.iter().filter(|&&aa| aa != AminoAcid::Stop).copied().collect();
267	    let back_mrna: Vec<u8> = {
268	        let mut v = Vec::new();
269	        for &aa in &non_stop {
270	            let codons = codons_for_aa_table(aa, code_table);
271	            if codons.is_empty() { break; }
272	            let c = &codons[0];
273	            v.push(b4_to_nucleotide(c.p1));
274	            v.push(b4_to_nucleotide(c.p2));
275	            v.push(b4_to_nucleotide(c.p3));
276	        }
277	        v
278	    };
279	    let mut roundtrip: Vec<AminoAcid> = Vec::new();
280	    let mut rpos = 0usize;
281	    while rpos + 2 < back_mrna.len() {
282	        match Codon::from_bytes(back_mrna[rpos], back_mrna[rpos+1], back_mrna[rpos+2]) {
283	            Ok(c) => {
284	                let aa = translate_codon_table(&c, code_table);
285	                if aa == AminoAcid::Stop { break; }
286	                roundtrip.push(aa);
287	            }
288	            Err(_) => break,
289	        }
290	        rpos += 3;
291	    }
292	    let frobenius_ok = !non_stop.is_empty()
293	        && non_stop.len() == roundtrip.len()
294	        && non_stop.iter().zip(roundtrip.iter()).all(|(a, b)| a == b);
295	
296	    // IG primitive labels per AA
297	    let primitive_labels: Vec<Option<&'static str>> = protein.iter()
298	        .map(|&aa| aa.primitive_name())
299	        .collect();
300	
301	    TranslationResult {
302	        mrna,
303	        protein,
304	        coding_length: coding_len,
305	        start_codon_pos: start.unwrap_or(0),
306	        stop_codon_present: stop_present,
307	        frobenius_verified: frobenius_ok,
308	        primitive_labels,
309	        code_table,
310	    }
311	}
312	
313	/// Run the reverse pipeline: protein chain → mRNA → DNA.
314	#[derive(Debug)]
315	pub struct ReverseTranslationResult {
316	    pub canonical_mrna: Vec<u8>,       // first codon per AA
317	    pub dna: Vec<u8>,                   // reverse-transcribed
318	    pub degeneracies: Vec<usize>,       // how many codons per AA position
319	    pub total_combinations: u64,        // product of degeneracies (capped)
320	    pub chain: Vec<AminoAcid>,
321	}
322	
323	/// Run protein → mRNA → DNA pipeline.
324	pub fn run_reverse_pipeline(chain: &[AminoAcid]) -> ReverseTranslationResult {
325	    run_reverse_pipeline_table(chain, CodeTable::Standard)
326	}
327	
328	pub fn run_reverse_pipeline_table(chain: &[AminoAcid], table: CodeTable) -> ReverseTranslationResult {
329	    use crate::rebis::genetics::codons_for_aa_table;
330	
331	    let canonical_mrna: Vec<u8> = {
332	        let mut v = Vec::new();
333	        for &aa in chain {
334	            let codons = codons_for_aa_table(aa, table);
335	            if codons.is_empty() { break; }
336	            let c = &codons[0];
337	            v.push(b4_to_nucleotide(c.p1));
338	            v.push(b4_to_nucleotide(c.p2));
339	            v.push(b4_to_nucleotide(c.p3));
340	        }
341	        v
342	    };
343	    let dna = reverse_transcribe(&canonical_mrna);
344	
345	    let degeneracies: Vec<usize> = chain.iter()
346	        .map(|&aa| codons_for_aa_table(aa, table).len())
347	        .collect();
348	
349	    // Compute total combinations (cap at u64::MAX)
350	    let mut total: u64 = 1;
351	    for &d in &degeneracies {
352	        if d == 0 { total = 0; break; }
353	        total = total.saturating_mul(d as u64);
354	    }
355	
356	    ReverseTranslationResult {
357	        canonical_mrna,
358	        dna,
359	        degeneracies,
360	        total_combinations: total,
361	        chain: chain.to_vec(),
362	    }
363	}
364	
365	// keep old run_reverse_pipeline stub above
366	
367	// ── Formatting ──────────────────────────────────────────────────
368	
369	/// Format amino acid chain as a 3-letter dash-separated string.
370	pub fn format_chain(chain: &[AminoAcid]) -> String {
371	    let mut s = String::new();
372	    for (i, aa) in chain.iter().enumerate() {
373	        if i > 0 { s.push('-'); }
374	        s.push_str(aa.name());
375	    }
376	    s
377	}
378	
379	/// Format amino acid chain as a 1-letter string (no separator).
380	pub fn format_chain_1letter(chain: &[AminoAcid]) -> String {
381	    let mut s = String::new();
382	    for aa in chain {
383	        s.push_str(aa_letter(*aa));
384	    }
385	    s
386	}
387	
388	/// Parse a protein string: 3-letter codes (dash or space separated)
389	/// or 1-letter codes (compact string).
390	pub fn parse_chain(input: &str) -> Option<Vec<AminoAcid>> {
391	    let input = input.trim();
392	    if input.is_empty() {
393	        return Some(Vec::new());
394	    }
395	
396	    // Try 3-letter codes (separated by dash, space, or comma)
397	    if input.len() >= 3 && (input.contains('-') || input.contains(' ') || input.contains(',')) {
398	        let parts: Vec<&str> = input.split(&['-', ' ', ','][..])
399	            .filter(|s| !s.is_empty())
400	            .collect();
401	        let mut chain = Vec::with_capacity(parts.len());
402	        for part in parts {
403	            chain.push(parse_aa(part)?);
404	        }
405	        return Some(chain);
406	    }
407	
408	    // Try 1-letter codes (compact string, no separators)
409	    // Check if all chars are valid 1-letter AA codes
410	    let mut chain = Vec::with_capacity(input.len());
411	    for ch in input.chars() {
412	        let s: String = core::iter::once(ch).collect();
