1	// rebis/fold.rs — SerpentRod secondary & tertiary structure prediction
2	//
3	// Port of gene_to_protein_pipeline.py stages 4-5.
4	// SerpentRod invariant: windingNumber <= contacts + 1 (structural bound).
5	//
6	// Algorithm: Chou-Fasman-like propensity windows for secondary structure;
7	// hydrophobic collapse + disulfide + ionic pairing for tertiary contacts.
8	// All derivation from physical constants, zero hardcoded fold tables.
9	
10	use crate::rebis::AminoAcid;
11	
12	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
13	pub enum SecondaryLabel {
14	    Helix,
15	    Sheet,
16	    Coil,
17	}
18	
19	impl SecondaryLabel {
20	    pub fn symbol(self) -> &'static str {
21	        match self {
22	            Self::Helix => "H",
23	            Self::Sheet => "S",
24	            Self::Coil  => "C",
25	        }
26	    }
27	    pub fn name(self) -> &'static str {
28	        match self {
29	            Self::Helix => "helix",
30	            Self::Sheet => "sheet",
31	            Self::Coil  => "coil",
32	        }
33	    }
34	}
35	
36	#[derive(Copy, Clone, Debug)]
37	pub enum ContactKind {
38	    Hydrophobic,
39	    Disulfide,
40	    Ionic,
41	}
42	
43	impl ContactKind {
44	    pub fn name(self) -> &'static str {
45	        match self {
46	            Self::Hydrophobic => "hydrophobic",
47	            Self::Disulfide   => "disulfide",
48	            Self::Ionic       => "ionic",
49	        }
50	    }
51	}
52	
53	pub struct TertiaryContact {
54	    pub i: usize,
55	    pub j: usize,
56	    pub kind: ContactKind,
57	    pub confidence: u8,   // 0–100
58	}
59	
60	pub struct FoldResidue {
61	    pub aa: AminoAcid,
62	    pub position: usize,
63	    pub secondary: SecondaryLabel,
64	    pub contacts: usize,
65	    pub winding_number: usize,
66	}
67	
68	pub struct FoldResult {
69	    pub residues: alloc::vec::Vec<FoldResidue>,
70	    pub contacts: alloc::vec::Vec<TertiaryContact>,
71	    pub frobenius_ok: bool,
72	    pub unique_primitives: usize,
73	    pub ouroboricity_tier: &'static str,
74	}
75	
76	/// Chou-Fasman propensities as (helix, sheet, turn) × 100.
77	/// Source: gene_to_protein_pipeline.py CHOU_FASMAN dict.
78	fn chou_fasman(aa: AminoAcid) -> (u32, u32, u32) {
79	    match aa {
80	        AminoAcid::Ala  => (142, 83,  66),
81	        AminoAcid::Arg  => (98,  93,  95),
82	        AminoAcid::Asn  => (67,  89,  156),
83	        AminoAcid::Asp  => (101, 54,  146),
84	        AminoAcid::Cys  => (70,  119, 119),
85	        AminoAcid::Gln  => (111, 110, 98),
86	        AminoAcid::Glu  => (151, 37,  74),
87	        AminoAcid::Gly  => (57,  75,  156),
88	        AminoAcid::His  => (100, 87,  95),
89	        AminoAcid::Ile  => (108, 160, 47),
90	        AminoAcid::Leu  => (121, 130, 59),
91	        AminoAcid::Lys  => (116, 74,  101),
92	        AminoAcid::Met  => (145, 105, 60),
93	        AminoAcid::Phe  => (113, 138, 60),
94	        AminoAcid::Pro  => (57,  55,  152),
95	        AminoAcid::Ser  => (77,  75,  143),
96	        AminoAcid::Thr  => (83,  119, 96),
97	        AminoAcid::Trp  => (108, 137, 96),
98	        AminoAcid::Tyr  => (69,  147, 114),
99	        AminoAcid::Val  => (106, 170, 50),
100	        AminoAcid::Stop => (100, 100, 100),
101	    }
102	}
103	
104	fn is_hydrophobic(aa: AminoAcid) -> bool {
105	    aa.properties().0 > 0.0
106	}
107	
108	fn signed_charge(aa: AminoAcid) -> i8 {
109	    match aa {
110	        AminoAcid::Arg | AminoAcid::Lys => 1,
111	        AminoAcid::Asp | AminoAcid::Glu => -1,
112	        _ => 0,
113	    }
114	}
115	
116	/// Predict secondary and tertiary structure from an amino acid chain.
117	/// Returns a FoldResult with per-residue annotations and contact list.
118	pub fn fold_sequence(chain: &[AminoAcid]) -> FoldResult {
119	    let n = chain.len();
120	    if n == 0 {
121	        return FoldResult {
122	            residues: alloc::vec::Vec::new(),
123	            contacts: alloc::vec::Vec::new(),
124	            frobenius_ok: true,
125	            unique_primitives: 0,
126	            ouroboricity_tier: "O_0",
127	        };
128	    }
129	
130	    // ── Secondary structure (Chou-Fasman-like) ──────────────────
131	    let mut pred = alloc::vec![SecondaryLabel::Coil; n];
132	
133	    // Alpha-helix: window=4, sum > 4*103 = 412; extend while individual > 100
134	    {
135	        let mut i = 0;
136	        while i + 4 <= n {
137	            let sum: u32 = chain[i..i+4].iter().map(|&a| chou_fasman(a).0).sum();
138	            if sum > 412 {
139	                let mut j = i + 4;
140	                while j < n && chou_fasman(chain[j]).0 > 100 {
141	                    j += 1;
142	                }
143	                for k in i..j { pred[k] = SecondaryLabel::Helix; }
144	                i = j;
145	            } else {
146	                i += 1;
147	            }
148	        }
149	    }
150	
151	    // Beta-sheet: window=3, sum > 3*105 = 315; skip positions already helix; extend while > 100
152	    {
153	        let mut i = 0;
154	        while i + 3 <= n {
155	            let already_h = (i..i+3).any(|k| pred[k] == SecondaryLabel::Helix);
156	            if !already_h {
157	                let sum: u32 = chain[i..i+3].iter().map(|&a| chou_fasman(a).1).sum();
158	                if sum > 315 {
159	                    let mut j = i + 3;
160	                    while j < n && chou_fasman(chain[j]).1 > 100 && pred[j] != SecondaryLabel::Helix {
161	                        j += 1;
162	                    }
163	                    for k in i..j { pred[k] = SecondaryLabel::Sheet; }
164	                    i = j;
165	                } else {
166	                    i += 1;
167	                }
168	            } else {
169	                i += 1;
170	            }
171	        }
172	    }
173	
174	    // ── Tertiary contacts ────────────────────────────────────────
175	    let mut contacts: alloc::vec::Vec<TertiaryContact> = alloc::vec::Vec::new();
176	    let min_seq_dist = { let d = n / 4; if d < 2 { 2 } else if d > 4 { 4 } else { d } };
177	
178	    // Hydrophobic contacts: pairs of hydrophobic residues > min_seq_dist apart
179	    {
180	        let hydro: alloc::vec::Vec<usize> = (0..n).filter(|&k| is_hydrophobic(chain[k])).collect();
181	        for a in 0..hydro.len() {
182	            for b in a+1..hydro.len() {
