[package]
name = "vox"
version = "0.1.0"
edition = "2021"
description = "V⊙x — lift program CFGs to the twelve-glyph IMASM word and verdict their closure"
license = "Unlicense"

# Standalone: no external crates. The decoder and lifter are pure Rust over
# `alloc`, so Vox builds on its own — it does not require mOMonadOS or any other
# repo present. Consumers that want the auditor as a library link this crate.
[lib]
name = "vox"
path = "src/lib.rs"

[[bin]]
name = "vox"
path = "src/main.rs"

[profile.release]
opt-level = 3
lto = true
---
//! V⊙x — the control-flow closure auditor, standalone.
//!
//! `vox_decode` is a native x86-64 decoder and ELF reader (no capstone, no
//! pefile). `vox` lifts a decoded instruction stream to a twelve-glyph IMASM
//! word and verdicts whether it closes: T closes, B holds a fork open across a
//! terminal, N never forked, F is ill-typed (a ∋ with no ∈). Both modules are
//! `no_std`+`alloc` and depend on nothing outside this crate, so a consumer
//! links `vox` the way every project links the foundation.
#![no_std]

#[macro_use]
extern crate alloc;

pub mod vox;
pub mod vox_decode;
pub mod lanes;
pub mod genetic;
pub mod pyc;
pub mod pyc_table;
pub mod genetic_table;
pub mod x86;
pub mod imasm_module;
pub mod imasm_vm;
pub mod loader;

